// Every module from every course, in one flat list, each stamped with its courseId.
export const MODULES = COURSES.flatMap((c) => c.modules.map((m) => ({ ...m, courseId: c.id })));

export function getCourse(courseId) { return COURSES.find((c) => c.id === courseId) || null; }

// A pre-reader course is one where the student cannot yet read. Everything on screen has
// to work without words: spoken lessons, symbols instead of status labels, and tapping
// instead of typing. Reading aloud is the primary channel here, not an aid bolted on top.
// Some modules only make sense with a finger on glass: tracing letters, dragging blocks.
// Educators see a warning before assigning a course that contains one.
export function courseNeedsTouch(courseId) {
  return MODULES.some((m) => m.courseId === courseId && m.needsTouch === true);
}

export function isPreReader(courseId) {
  const c = getCourse(courseId);
  return !!(c && c.readAloud);
}

// How many questions a module asks, and how many must be right. A course can override
// both, because five quick questions suit counting while a physics module may want three
// long ones. Everything downstream reads these rather than assuming the default.
// The script a read-aloud lesson speaks: the lesson's own script, or one line per example caption, or one line per
// paragraph with the words inside [[ ]] shown on a card and never spoken. Every read-aloud lesson must yield one.
// The picture and letter names a question asks for by name (pass JR). Tap the moon asks for the moon and Tap the letter B
// for B, so the lesson must have said them; a name every choice shares is not asked (Tap the red square, between a red
// square and a blue one, asks for red), and a question that names nothing (Tap the one that is the same) asks for none.
export function askedNames(q) {
  if (!q || q.type !== 'choice' || typeof q.answer !== 'string') return [];
  const asked = String(q.prompt || '').toLowerCase();
  const named = (w) => new RegExp(`\\b${w}s?\\b`).test(asked);
  const parts = (x) => { const s = String(x).replace(/#\d+$/, ''); let m;
    if ((m = /^(?:icon|pic|art|shape|solid):([a-z]+)/.exec(s))) return [m[1]];
    if ((m = /^swatch:([a-z]+)$/.exec(s))) return [m[1]];
    if ((m = /^item:([a-z]+)-([a-z]+)/.exec(s))) return [m[1], m[2]];
    return null; };
  const mine = parts(q.answer);
  if (mine) { const others = (q.choices || []).filter((c) => c !== q.answer).map(parts).filter(Boolean); return mine.filter((w) => named(w) && others.some((o) => !o.includes(w))); }
  if (/^[A-Z]$/.test(q.answer) && /\bletter\b/.test(asked)) return [q.answer];
  return [];
}
export function readAloudScript(mod) {
  if (!mod || !mod.lesson) return [];
  if (Array.isArray(mod.lesson.script) && mod.lesson.script.length) return mod.lesson.script;
  // A lesson with no script of its own speaks every paragraph, each beside its [[ ]] card or else the lesson's example, and
  // then the example's caption (pass JP). Before pass JP a lesson with an example spoke only that caption, so the
  // kindergarten electives, health, music and Writing numbers reached a pre-reader as one line and never spoke their teaching.
  const ex = mod.lesson.example || null;
  const lines = (mod.lesson.paragraphs || []).map((t) => { const shown = [...t.matchAll(/\[\[(.*?)\]\]/g)].map((m) => m[1].trim()); const say = t.replace(/\[\[.*?\]\]/g, ' ').replace(/\s+/g, ' ').trim(); return { say, show: shown.length ? { kind: 'letters', text: shown.join('   ') } : ex }; });
  if (ex && ex.caption) lines.push({ say: ex.caption, show: ex });
  return lines.filter((line) => line.say || line.show);
}
export function moduleRules(moduleId) {
  const mod = getModule(moduleId);
  const course = mod ? getCourse(mod.courseId) : null;
  // Older students get longer rounds at the same bar: eight questions from grade 6 (seven to master), ten from grade 9
  // (eight to master). A module or course that sets its own numbers keeps them.
  const at = course ? GRADES.indexOf(course.grade) : -1;
  const byGrade = at >= GRADES.indexOf('9') ? { questions: 10, toMaster: 8 } : at >= GRADES.indexOf('6') ? { questions: 8, toMaster: 7 } : null;
  return {
    questions: (mod && mod.questions) || (course && course.questionsPerAttempt) || (byGrade && byGrade.questions) || CONFIG.CORE_QUESTIONS_PER_ATTEMPT,
    toMaster: (mod && mod.toMaster) || (course && course.questionsToMaster) || (byGrade && byGrade.toMaster) || CONFIG.MASTERY_MIN_CORRECT,
  };
}

// Grades that actually have courses, in order — so a grade with nothing in it is never offered.
export function gradesWithCourses() { return GRADES.filter((g) => COURSES.some((c) => c.grade === g)); }

// Courses for one grade, grouped by subject: [{ subject, courses: [...] }, ...]
// Which courses are worth showing first. Once a placement check exists it decides this.
// Until then we go with the grades a student is already working in, and fall back to the
// earliest grade we have, so a brand new student is never shown a wall of thirteen grades.
// When every module of a course is mastered, the next course up in the same subject is
// ready to be switched on. Returns the ids to add, so the screen can record it as an
// event and tell the student. A placement check, once built, will jump further.
// Coloring: pure play, no grade and no score. One picture is there from the start, and every
// course the student finishes adds another. The pictures themselves are drawn by the screen.
// Ordered simplest first: a ball of two parts for a three-year-old, a city of twenty for the end
// of grade 2. One more picture is earned for every module passed, so they arrive steadily.
const DRAWINGS = ['ball', 'sun', 'balloon', 'my-name', 'star', 'tree', 'house', 'fish', 'cat', 'flower', 'boat', 'rocket', 'butterfly', 'train', 'car', 'robot', 'fishbowl', 'castle', 'dinosaur', 'city', 'playground', 'farm', 'birthday', 'kite', 'ladybug', 'ice-cream', 'snowman', 'hot-air-balloon', 'lighthouse', 'treehouse', 'submarine', 'pirate-ship', 'dragon', 'space-station', 'jungle-waterfall', 'aquarium', 'race-track', 'busy-harbor', 'dinosaur-valley'];
// Letter pages: a capital beside its lowercase, with a few circles around them to color too, and the
// letter's name spoken on opening. They take turns with the drawings, so the alphabet arrives one
// letter at a time from the very first pictures.
export const LETTER_PICTURES = 'abcdefghijklmnopqrstuvwxyz'.split('').map((ch) => `letter-${ch}`);
export const COLORING_PICTURES = DRAWINGS.flatMap((pic, i) => (LETTER_PICTURES[i] ? [pic, LETTER_PICTURES[i]] : [pic])).concat(LETTER_PICTURES.slice(DRAWINGS.length));
export function pictureTitle(pic) { if (pic.startsWith('lesson-')) { const mod = MODULES.find((x) => x.id === pic.slice(7)); return mod ? mod.title : 'Picture'; } return pic === 'my-name' ? 'My name' : pic.startsWith('letter-') ? `Letter ${pic.slice(-1).toUpperCase()}` : pic.replace(/-/g, ' '); }

