  const deal = [...mix(CAUSE_STUDIES.filter((c) => c[1] === 'experiment')).slice(0, 3), ...mix(CAUSE_STUDIES.filter((c) => c[1] === 'correlation')).slice(0, 3)];
  return mix(deal).map(([text, answer, why]) => ({ text, answer, why }));
