const FLAWS = [
  { text: 'I met one rude person from that town, so everyone there must be rude.', flaw: 'Overgeneralizing' },
  { text: 'Our team lost right after I wore my new socks, so the socks made us lose.', flaw: 'False cause' },
  { text: 'You cannot be right about the budget; you were late to the meeting.', flaw: 'Attacking the person' },
  { text: 'Either we cancel the trip or someone gets hurt. There is no other way.', flaw: 'False choice' },
  { text: 'My two cousins hate broccoli, so kids in general hate broccoli.', flaw: 'Overgeneralizing' },
  { text: 'Ice cream sales and sunburns both rise in July, so ice cream causes sunburn.', flaw: 'False cause' },
  { text: 'Do not listen to her plan for the garden; she cannot even keep her desk tidy.', flaw: 'Attacking the person' },
  { text: 'Either you support the new rule or you do not care about safety.', flaw: 'False choice' },
];
const FLAW_NAMES = ['Overgeneralizing', 'False cause', 'Attacking the person', 'False choice'];
const FLAW_NOTES = { Overgeneralizing: 'Overgeneralizing is when one or two cases are treated as proof about everyone.', 'False cause': 'False cause is when one thing happened after another, so it is blamed for it.', 'Attacking the person': 'Attacking the person is when the speaker is criticized instead of the idea.', 'False choice': 'False choice is when only two options are offered as if no others exist.' };
const SOUND_ARGUMENTS = ['Over three years, streets with speed bumps had fewer crashes than streets without, so speed bumps likely help.', 'A survey of 800 students found most prefer a later start, which supports moving the bell.', 'The bridge inspection found rust in two supports, so repairs are needed before winter.'];
const IRONIES = [
  { text: 'The fire station burned to the ground.', type: 'Situational irony' },
  { text: 'Soaked to the skin, she said, "What lovely weather we are having."', type: 'Verbal irony' },
  { text: 'The audience knows the letter is a prank, but the hero reads it as a marriage proposal and rushes to buy flowers.', type: 'Dramatic irony' },
  { text: 'The lifeguard had to be rescued from the pool.', type: 'Situational irony' },
  { text: 'After the test he groaned, "Well, that was a breeze."', type: 'Verbal irony' },
  { text: 'We know the vase is already broken; the boy keeps promising his mother he will guard it with his life.', type: 'Dramatic irony' },
];
const IRONY_TYPES = ['Situational irony', 'Verbal irony', 'Dramatic irony'];
const IRONY_NOTES = { 'Situational irony': 'Situational irony is when what happens is the opposite of what anyone would expect.', 'Verbal irony': 'Verbal irony is when what is said is the opposite of what is meant.', 'Dramatic irony': 'Dramatic irony is when the audience knows something a character does not.' };
const NOT_IRONIC = ['She missed the bus and had to walk.', 'It rained on the day of the picnic.', 'He forgot his umbrella and got wet.'];
const IRONIC_ONLY = ['The plumber\'s own kitchen sink leaked for a year.', 'The spelling bee champion misspelled the word "champion" on her trophy form.', 'The traffic officer got a parking ticket outside the police station.'];
const ALLUSIONS = [
  { phrase: 'an Achilles heel', meaning: 'a single weak spot', source: 'a Greek hero who could only be wounded in the heel' },
  { phrase: 'a Herculean task', meaning: 'an enormous, almost impossible job', source: 'a hero who completed twelve impossible labors' },
  { phrase: 'opening Pandora\'s box', meaning: 'letting loose troubles you cannot take back', source: 'a myth about a box that held every trouble in the world' },
  { phrase: 'a Trojan horse', meaning: 'a trick that hides an attack inside a gift', source: 'a wooden horse that hid soldiers inside a city\'s walls' },
  { phrase: 'a Midas touch', meaning: 'the ability to make anything succeed', source: 'a king whose touch turned things to gold' },
  { phrase: 'crying wolf', meaning: 'raising false alarms until nobody believes you', source: 'a fable about a shepherd boy who lied about a wolf' },
  { phrase: 'a David and Goliath contest', meaning: 'a small opponent against a giant one', source: 'a story of a shepherd who defeated a giant' },
  { phrase: 'a Scrooge', meaning: 'a mean, stingy person', source: 'a character who hated spending and hated Christmas' },
];
const SUMMARY_PAIRS = [
  { objective: 'The article argues that the park should close at dusk, citing two nighttime accidents.', loaded: 'The article makes a silly case for closing the park over two tiny accidents.', word: 'whines', neutral: 'argues' },
  { objective: 'The author claims the new bus route saves riders time and supports it with a survey.', loaded: 'The author pretends the new bus route saves time, waving around some survey.', word: 'pretends', neutral: 'claims' },
  { objective: 'The report describes a rise in library visits since the hours were extended.', loaded: 'The report brags about a supposed rise in library visits.', word: 'brags', neutral: 'reports' },
  { objective: 'The essay argues that homework should be limited and offers three studies as support.', loaded: 'The essay insists, with the usual excuses, that homework should be limited.', word: 'insists', neutral: 'argues' },
];
const NEUTRAL_VERBS = ['argues', 'claims', 'reports', 'describes'];
Object.assign(GENERATORS, {
  'r8-name-flaw': (rng) => {
    const f = pick(rng, FLAWS);
    return { type: 'choice', story: f.text, prompt: 'What is the flaw in this reasoning?', choices: shuffle(rng, FLAW_NAMES), answer: f.flaw,
      explain: `${FLAW_NOTES[f.flaw]}\nThe claim may still be true, but the argument has not earned it.`, choiceNotes: FLAW_NOTES, visual: null, explainVisual: null };
  },
  'r8-which-flawed': (rng) => {
    const f = pick(rng, FLAWS); const sound = pick(rng, SOUND_ARGUMENTS);
    return { type: 'choice', story: null, prompt: 'Which argument is flawed?', choices: shuffle(rng, [f.text, sound]), answer: f.text,
      explain: `The flawed one is ${f.flaw.toLowerCase()}. The other rests on evidence that could be checked.`, visual: null, explainVisual: null };
  },
  'r8-irony-type': (rng) => {
    const i = pick(rng, IRONIES);
    return { type: 'choice', story: i.text, prompt: 'What kind of irony is this?', choices: shuffle(rng, IRONY_TYPES), answer: i.type,
      explain: IRONY_NOTES[i.type], choiceNotes: IRONY_NOTES, visual: null, explainVisual: null };
  },
  'r8-is-ironic': (rng) => {
    const ironic = pick(rng, IRONIC_ONLY); const plain = pick(rng, NOT_IRONIC);
    return { type: 'choice', story: null, prompt: 'Which of these is ironic, not just unlucky?', choices: shuffle(rng, [ironic, plain]), answer: ironic,
      explain: 'Irony needs a gap between what is expected and what happens. Bad luck alone is not irony.', visual: null, explainVisual: null };
  },
  'r8-allusion-meaning': (rng) => {
    const a = pick(rng, ALLUSIONS); const others = shuffle(rng, ALLUSIONS.filter((x) => x !== a)).slice(0, 2).map((x) => x.meaning);
    return { type: 'choice', story: `"${a.phrase}"`, prompt: 'What does this allusion mean?', choices: shuffle(rng, [a.meaning, ...others]), answer: a.meaning,
      explain: `It points to ${a.source}.`, visual: null, explainVisual: null };
  },
  'r8-allusion-source': (rng) => {
    const a = pick(rng, ALLUSIONS); const others = shuffle(rng, ALLUSIONS.filter((x) => x !== a)).slice(0, 2).map((x) => x.source);
    return { type: 'choice', story: `"${a.phrase}"`, prompt: 'What story does this allusion point to?', choices: shuffle(rng, [a.source, ...others]), answer: a.source,
      explain: `${a.phrase} means ${a.meaning}, from ${a.source}.`, visual: null, explainVisual: null };
  },
  'r8-objective-summary': (rng) => {
    const pair = pick(rng, SUMMARY_PAIRS);
    return { type: 'choice', story: null, prompt: 'Which summary is objective?', choices: shuffle(rng, [pair.objective, pair.loaded]), answer: pair.objective,
      explain: 'The objective one says what the text says. The other adds a judgment.', visual: null, explainVisual: null };
  },
  'r8-loaded-word': (rng) => {
    const pair = pick(rng, SUMMARY_PAIRS); const others = shuffle(rng, NEUTRAL_VERBS.filter((v) => v !== pair.neutral)).slice(0, 2);
    return { type: 'choice', story: `The word "${pair.word}" leaks an opinion into a summary.`, prompt: 'Which neutral word could replace it?', choices: shuffle(rng, [pair.neutral, ...others]), answer: pair.neutral,
      explain: `${capFirst(pair.word)} judges. ${capFirst(pair.neutral)} only reports.`, visual: null, explainVisual: null };
  },

  // ---- Grade 9 math ----
  'g9-both-sides': (rng) => {
    const x = randInt(rng, 1, 9); const a = randInt(rng, 3, 7); const b = randInt(rng, 1, a - 1); const c = randInt(rng, 1, 9); const d = (a - b) * x + c;
    const wrongs = [x + 1, x - 1, d - c].filter((v) => v !== x && v > 0);
    return { type: 'choice', story: null, prompt: `${a}x + ${c} = ${b}x + ${d}. What is x?`, choices: shuffle(rng, [x, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(x),
      explain: `First, you subtract ${b}x from both sides to get: **${a - b}x + ${c} = ${d}**\nThen, you subtract ${c} to remove it from the left side: **${a - b}x = ${d - c}**\nThen, you divide both sides by ${a - b} to further isolate the **x**: **x = ${x}**`, visual: null, explainVisual: null };
  },
  'g9-distribute-solve': (rng) => {
    const x = randInt(rng, 1, 9); const a = randInt(rng, 2, 6); const b = randInt(rng, 1, 8); const total = a * (x + b);
    const wrongs = [x + 1, total / a, x + b].filter((v) => v !== x && v > 0 && Number.isInteger(v));
    return { type: 'choice', story: null, prompt: `${a}(x + ${b}) = ${total}. What is x?`, choices: shuffle(rng, [x, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(x),
      explain: `First, you multiply out the parentheses: **${a}x + ${a * b} = ${total}**\nThen, you subtract ${a * b} from both sides: **${a}x = ${total - a * b}**\nThen, you divide both sides by ${a} to leave the **x** alone: **x = ${x}**`, visual: null, explainVisual: null };
  },
  'g9-evaluate-function': (rng) => {
    const m = randInt(rng, 2, 6); const c = randInt(rng, -5, 9); const x = randInt(rng, 1, 8); const right = m * x + c;
    const wrongs = [m + x + c, right + m, m * x].filter((v) => v !== right);
    return { type: 'choice', story: `f(x) = ${m}x ${c < 0 ? '- ' + Math.abs(c) : '+ ' + c}`, prompt: `What is f(${x})?`, choices: shuffle(rng, [right, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(right),
      explain: `Put ${x} in for x: ${m} x ${x} ${c < 0 ? '- ' + Math.abs(c) : '+ ' + c} = ${right}.`, visual: null, explainVisual: null };
  },
  'g9-find-input': (rng) => {
    const m = randInt(rng, 2, 6); const c = randInt(rng, 0, 9); const x = randInt(rng, 1, 8); const out = m * x + c;
    const wrongs = [x + 1, out, x - 1].filter((v) => v !== x && v > 0);
    return { type: 'choice', story: `f(x) = ${m}x + ${c}`, prompt: `For what x does f(x) = ${out}?`, choices: shuffle(rng, [x, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(x),
      explain: `${m}x + ${c} = ${out}, so ${m}x = ${out - c} and x = ${x}.`, visual: null, explainVisual: null };
  },
  'g9-is-function': (rng) => {
    const yes = randInt(rng, 0, 1) === 1; const a = randInt(rng, 1, 5); const b = a + randInt(rng, 1, 3);
    const pairs = yes ? `(${a}, 3), (${b}, 3), (${b + 1}, 7)` : `(${a}, 3), (${a}, 5), (${b}, 7)`;
    return { type: 'choice', story: pairs, prompt: 'Is this a function?', choices: ['Yes', 'No'], answer: yes ? 'Yes' : 'No',
      explain: yes ? 'Every input has exactly one output, even though two share the same output.' : `The input ${a} appears twice with different outputs, so it is not a function.`, visual: null, explainVisual: null };
  },
  'g9-system-substitute': (rng) => {
    const x = randInt(rng, 1, 6); const a = randInt(rng, 1, 5); const m = a + randInt(rng, 1, 3); const y = x + a; const c = y - m * x;
    const right = `x = ${x}, y = ${y}`; const wrongs = [`x = ${y}, y = ${x}`, `x = ${x + 1}, y = ${y + 1}`, `x = ${x}, y = ${y - 1}`];
    return { type: 'choice', story: `y = x + ${a} and y = ${m}x ${c < 0 ? '- ' + Math.abs(c) : '+ ' + c}`, prompt: 'What pair solves both equations?', choices: shuffle(rng, [right, ...wrongs]), answer: right,
      explain: `x + ${a} = ${m}x ${c < 0 ? '- ' + Math.abs(c) : '+ ' + c}, so ${m - 1}x = ${a - c} and x = ${x}. Then y = ${y}.`, visual: null, explainVisual: null };
  },
  'g9-check-pair': (rng) => {
    const x = randInt(rng, 1, 6); const a = randInt(rng, 1, 5); const y = x + a; const m = randInt(rng, 2, 4); const c = y - m * x; const yes = randInt(rng, 0, 1) === 1;
    const px = yes ? x : x + 1; const py = yes ? y : y;
    return { type: 'choice', story: `y = x + ${a} and y = ${m}x ${c < 0 ? '- ' + Math.abs(c) : '+ ' + c}`, prompt: `Does x = ${px}, y = ${py} solve both equations?`, choices: ['Yes', 'No'], answer: yes ? 'Yes' : 'No',
      explain: yes ? 'Both equations are true for that pair.' : `The first gives y = ${px + a}, not ${py}, so no.`, visual: null, explainVisual: null };
  },
  'g9-factor-pair': (rng) => {
    const p = randInt(rng, 1, 6); const q = randInt(rng, 1, 6); const b = p + q; const c = p * q; const right = `${Math.min(p, q)} and ${Math.max(p, q)}`;
    const wrongs = [`${p} and ${q + 1}`, `${b} and ${c}`, `1 and ${c}`].filter((v) => v !== right);
    return { type: 'choice', story: `x^2 + ${b}x + ${c}`, prompt: `Which two numbers multiply to ${c} and add to ${b}?`, choices: shuffle(rng, [right, ...[...new Set(wrongs)].slice(0, 3)]), answer: right,
      explain: `${p} x ${q} = ${c} and ${p} + ${q} = ${b}.`, visual: null, explainVisual: null };
  },
  'g9-factor-trinomial': (rng) => {
    const p = randInt(rng, 1, 6); const q = randInt(rng, 1, 6); const b = p + q; const c = p * q; const lo = Math.min(p, q); const hi = Math.max(p, q);
    const right = `(x + ${lo})(x + ${hi})`; const wrongs = [`(x + ${lo + 1})(x + ${hi})`, `(x + 1)(x + ${c})`, `(x + ${b})(x + ${c})`].filter((v) => v !== right);
    return { type: 'choice', story: null, prompt: `Factor x^2 + ${b}x + ${c}.`, choices: shuffle(rng, [right, ...[...new Set(wrongs)].slice(0, 3)]), answer: right,
      explain: `${lo} and ${hi} multiply to ${c} and add to ${b}.`, visual: null, explainVisual: null };
  },
  'g9-zeros': (rng) => {
    const p = randInt(rng, 1, 6); let q = randInt(rng, 1, 6); if (q === p) q = p + 1; const lo = Math.min(p, q); const hi = Math.max(p, q);
    const right = `x = -${lo} or x = -${hi}`; const wrongs = [`x = ${lo} or x = ${hi}`, `x = -${lo} or x = ${hi}`, `x = 0 or x = -${hi}`];
    return { type: 'choice', story: `(x + ${lo})(x + ${hi}) = 0`, prompt: 'What are the solutions?', choices: shuffle(rng, [right, ...wrongs]), answer: right,
      explain: 'One factor must be zero, so x is the opposite of each number.', visual: null, explainVisual: null };
  },
  'g9-linear-or-exponential': (rng) => {
    const start = randInt(rng, 2, 9); const exp = randInt(rng, 0, 1) === 1; const step = randInt(rng, 2, 4);
    const seq = exp ? [start, start * step, start * step * step, start * step * step * step] : [start, start + step, start + 2 * step, start + 3 * step];
    return { type: 'choice', story: seq.join(', '), prompt: 'Is this growth linear or exponential?', choices: ['Linear', 'Exponential'], answer: exp ? 'Exponential' : 'Linear',
      explain: exp ? `Each step multiplies by ${step}: the same ratio, so exponential.` : `Each step adds ${step}: the same difference, so linear.`, visual: null, explainVisual: null };
  },
  'g9-growth-value': (rng) => {
    const start = pick(rng, [10, 20, 50, 100]); const rate = randInt(rng, 2, 3); const t = randInt(rng, 2, 5); const right = start * rate ** t;
    const wrongs = [start * rate * t, start + rate ** t, start * rate ** (t - 1)].filter((v) => v !== right);
    return { type: 'choice', story: `A population starts at ${start} and multiplies by ${rate} every year.`, prompt: `How big is the population after ${t} years?`, choices: shuffle(rng, [right, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(right),
      explain: `${start} x ${rate}^${t} = ${start} x ${rate ** t} = ${right}.`, visual: null, explainVisual: null };
  },
  'g9-next-term': (rng) => {
    const start = randInt(rng, 2, 6); const ratio = randInt(rng, 2, 3); const seq = [start, start * ratio, start * ratio * ratio]; const right = start * ratio ** 3;
    const wrongs = [seq[2] + (seq[2] - seq[1]), right + ratio, seq[2] * ratio + 1].filter((v) => v !== right);
    return { type: 'choice', story: `${seq.join(', ')}, ...`, prompt: 'What is the next number?', choices: shuffle(rng, [right, ...[...new Set(wrongs)].slice(0, 3)].map(String)), answer: String(right),
      explain: `Each step multiplies by ${ratio}: ${seq[2]} x ${ratio} = ${right}.`, visual: null, explainVisual: null };
  },
});

