const REV_EVENTS = [{ year: 1765, event: 'The Stamp Act taxes paper' }, { year: 1770, event: 'British soldiers fire on a crowd in Boston' }, { year: 1773, event: 'Colonists dump tea into Boston Harbor' }, { year: 1775, event: 'Shots at Lexington and Concord' }, { year: 1776, event: 'The Declaration of Independence' }];
