// A skill's place in the list is its maturity. First is earliest, last is most mature.
// The screen uses that position to shade each one, from the palest green at the top to
// deep forest green at the bottom.
// Markers down the single scrolling column. They give a long list some structure
// without breaking the sense of one continuous sequence.
export const LIFE_STAGES = [
  { id: 'early', title: 'Early', blurb: 'First steps towards doing things without help.' },
  { id: 'growing', title: 'Growing up', blurb: 'Skills that need a little independence to practice.' },
  { id: 'teen', title: 'Teen', blurb: 'Bigger responsibilities, and the habits that carry into adult life.' },
  { id: 'grown', title: 'Nearly grown', blurb: 'The things nobody teaches you before you suddenly need them.' },
];

export function lifeSkillsInOrder() {
  const total = LIFE_SKILLS.length;
  return LIFE_SKILLS.map((sk, i) => ({
    ...sk,
    position: i + 1,
    total,
    stage: sk.stage || 'early',
    // 0 for the very first skill, 1 for the last. The screen turns this into a colour.
    maturity: total <= 1 ? 0 : Math.round((i / (total - 1)) * 100) / 100,
  }));
}

// Which skills a classroom has already covered. This is the educator's own bookmark.
// It is never attached to a student, which keeps the whole section outside the student
// record and out of reach of the privacy rules that govern everything else.
export function emptyCoveredSkills() { return { version: 1, covered: [] }; }
export function isCovered(state, id) { return state.covered.includes(id); }
export function toggleCovered(state, id) {
  return { ...state, covered: state.covered.includes(id) ? state.covered.filter((x) => x !== id) : [...state.covered, id] };
}
export function coveredCount(state, skills) { return skills.filter((sk) => state.covered.includes(sk.id)).length; }

// ---------------------------------------------------------------------
// 9. BACKUP FILES — the whole classroom in one file
//    Local-first: nothing lives on a server. The record of what happened is the
//    truth, so a file holding every record is a complete backup, and restoring it on
//    another device recreates everything. Restoring never overwrites: event logs are
//    joined, and the roster is merged by student id, so restoring an old file onto a
//    newer device can only add history, never lose it.
// ---------------------------------------------------------------------
export const BACKUP_VERSION = 1;

// A moment written out plainly for a person: "Saturday, September 12, 2026 at 12:35 AM Central Daylight Time".
export function describeMoment(at) {
  const d = new Date(at);
  if (Number.isNaN(d.getTime())) return String(at);
  try {
    const date = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
    const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZoneName: 'long' });
    return `${date} at ${time}`;
  } catch (e) { return d.toString(); }
}

export function buildBackup({ roster, records, wonderReview, covered, deviceName, recovery }, at) {
  return {
    app: 'The Wise Human',
    // First thing in the file, so anyone who opens it sees it at once. Proof of ownership
    // for a PIN reset: only this classroom's backups carry it, and a student does not have
    // the educator's backup file. It can also be typed in instead of choosing the file.
    recovery: recovery || null,
    recoveryNote: recovery ? 'RECOVERY CODE. Keep this file somewhere safe. To reset a forgotten educator PIN, choose this file on the sign-in screen or type the code above.' : null,
    version: BACKUP_VERSION,
    // Two forms of the same moment: one a person can read at a glance, in the device's own
    // time zone, and one a machine can sort and compare.
    saved: describeMoment(at),
    savedAt: at,
    deviceName: String(deviceName || '').trim() || null,
    studentIds: roster.students.filter((s) => s.active).map((s) => s.id),
    roster,
    records: records.map((r) => ({ name: r.name, events: r.events })),
    wonderReview,
    covered,
  };
}

// A file name that says where it came from and what it holds, so a folder of backups
// from ten devices can be read without opening anything:
// wise-human-ipad-3-12-students-2026-09-10.json
export function backupFileName(deviceName, studentCount, at) {
  // Apostrophes vanish rather than becoming hyphens, so "Mike's laptop" reads as mikes-laptop.
  const device = String(deviceName || 'device').trim().toLowerCase().replace(/['\u2019]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'device';
  return `wise-human-${device}-${studentCount}-${studentCount === 1 ? 'student' : 'students'}-${backupStamp(at)}.json`;
}

// The date and time in the file name, in local time and the American order: 9-11-2026-10-43pm.
// Two backups on one day then get two names, and a folder sorts them by name and reads well.
export function backupStamp(at) {
  const d = new Date(at);
  if (Number.isNaN(d.getTime())) return String(at).slice(0, 10);
  const h24 = d.getHours(); const h = h24 % 12 === 0 ? 12 : h24 % 12; const mm = String(d.getMinutes()).padStart(2, '0');
  return `${d.getMonth() + 1}-${d.getDate()}-${d.getFullYear()}-${h}-${mm}${h24 < 12 ? 'am' : 'pm'}`;
}

// Checks a file before anything is merged from it. Returns a plain sentence on failure.
export function checkBackup(data) {
  if (!data || typeof data !== 'object') return 'That file is not a backup from The Wise Human.';
  if (data.app !== 'The Wise Human' && data.app !== 'EduSphere') return 'That file is not a backup from The Wise Human.';   // backups made before the rename say The Wise Human (2026-09-24)
  if (typeof data.version !== 'number' || data.version > BACKUP_VERSION) return 'That backup was made by a newer version of The Wise Human. Update the app and try again.';
  if (!data.roster || !Array.isArray(data.roster.students)) return 'That backup has no student list in it.';
  if (!Array.isArray(data.records)) return 'That backup has no student records in it.';
  return null;
}

// Joins a backup into what is already on this device. Students are matched by id, events
// are joined in time order without duplicates, and the educator's own settings (which
// reflection questions are approved, which skills are covered) take the union.
export function mergeBackup(current, backup) {
  const students = [...current.roster.students];
  for (const st of backup.roster.students) {
    const i = students.findIndex((x) => x.id === st.id);
    if (i < 0) students.push(st);
    else students[i] = { ...st, ...students[i], active: students[i].active || st.active };
  }
  const records = new Map(current.records.map((r) => [r.name, r]));
  for (const r of backup.records) {
    const existing = records.get(r.name);
    if (!existing) { records.set(r.name, { name: r.name, events: [...r.events] }); continue; }
    const seen = new Set(existing.events.map((e) => JSON.stringify(e)));
    const added = r.events.filter((e) => !seen.has(JSON.stringify(e)));
    records.set(r.name, { name: r.name, events: mergeEventLogs(existing.events, added) });
  }
  const union = (a, b) => [...new Set([...(a || []), ...(b || [])])];
  return {
    roster: { ...current.roster, students },
    records: [...records.values()],
    wonderReview: { version: 1, approved: union(current.wonderReview.approved, backup.wonderReview && backup.wonderReview.approved), hidden: union(current.wonderReview.hidden, backup.wonderReview && backup.wonderReview.hidden) },
    covered: { version: 1, covered: union(current.covered.covered, backup.covered && backup.covered.covered) },
    addedStudents: backup.roster.students.filter((st) => !current.roster.students.some((x) => x.id === st.id)).length,
  };
}

// A random recovery code, made once when the educator account is created. It lives in
// the educator profile on the device and inside every backup file. Resetting a
// forgotten PIN means showing a backup that carries the matching code.
export function makeRecoveryCode(seed) {
  const rng = makeRng(seed);
  return Array.from({ length: 4 }, () => randInt(rng, 1000, 9999)).join('-');
}
export function backupProvesOwnership(backup, recovery) {
  return !!(recovery && backup && backup.recovery && String(backup.recovery) === String(recovery));
}
// The same check for a code typed by hand: spaces and case do not matter.
export function codeMatches(typed, recovery) {
  const clean = (x) => String(x || '').replace(/[^0-9]/g, '');
  return !!(recovery && clean(typed).length === 16 && clean(typed) === clean(recovery));
}

// How long since the last backup, in whole days, or null if there has never been one.
export function daysSinceBackup(lastAt, now) {
  if (!lastAt) return null;
  return Math.floor((new Date(now) - new Date(lastAt)) / 86400000);
}

// ---------------------------------------------------------------------
// 3. CORE RULES
// ---------------------------------------------------------------------

// -----------------------------------------------------------------------------------------------------------------
// questionKey (2026-10-01, pass HS). In plain terms: what makes two questions the same question. It is the setup, the
// wording, the picture, the answer and the set of answers offered (in any order). Two picture tasks with the same words
// but different pictures, such as two different "tap the bigger one" boards, are different questions; the same item
// from a fixed bank, with its choices shuffled, is the same question. Rounds, memory checks, placement probes, the
// question-pool audit and the rules tests all use this one definition.
// -----------------------------------------------------------------------------------------------------------------
// What counts as the same question (pass IU, Mikey: the same question and answer twice in one Animal sounds round): the
// setup, the wording, the picture and the answer. The wrong choices are left out on purpose. Tap the animal that says
// buzz with a different wrong animal is still the same question to a child, and before this pass it counted as new.
export function questionKey(q) {
  if (!q) return '';
  return JSON.stringify([q.story || '', q.prompt || '', q.visual || null, q.answer === undefined ? null : q.answer, q.trace || q.target || null]);
}

// Builds one practice set for a module. Same (moduleId, seed, masteredIds) => same set.
//   core:   the questions that count toward mastery
//   review: one question from an EARLIER, already-mastered module (retention check only)
// options.dose: 1 for a normal round, 3 for a triple dose on a module the student keeps missing.
// options.avoid: prompts asked in recent rounds, so a repeat round reaches for questions not yet seen;
// the memory checks avoid their own module's recent prompts the same way (the alternate stack).
export function buildAttempt(moduleId, seed, masteredIds, options = {}) {
  const dose = options.dose && options.dose > 1 ? options.dose : 1;
  const avoid = new Set(options.avoid || []);
  const mod = getModule(moduleId);
  if (!mod) throw new Error(`Unknown module: ${moduleId}`);
  const rng = makeRng(seed);
  const order = shuffle(rng, mod.generators);
  const core = [];
  const howMany = moduleRules(moduleId).questions * dose;
  // Tracing and dot-to-dot tasks are motor practice with no answer to give away, so tracing a letter twice is allowed.
  const same = (q, taken) => { if (q.type === 'trace') return false; const k = questionKey(q); return taken.some((c) => questionKey(c) === k); };
  const fresh = (gen, taken) => {
    // Not one from the last rounds if another can be found, and many tries for one not yet in this round.
    let q = generateQuestion(gen, randInt(rng, 1, 2147483646));
    for (let tries = 0; tries < 40 && (same(q, taken) || (tries < 10 && avoid.has(q.prompt))); tries++) q = generateQuestion(gen, randInt(rng, 1, 2147483646));
    return q;
  };
  // Never the same question twice in one round (2026-10-01, pass HR, Mikey). In plain terms: when a bank has no new
  // question left, the module's other banks are tried; if none has one, the round ends early instead of repeating,
  // because a repeated question gives its answer away. Mastery needs the same share of a shorter round (coreTotal).
  const banks = [...new Set(mod.generators)];
  for (let i = 0; i < howMany; i++) {
    let q = fresh(order[i % order.length], core);
    for (const g of banks) { if (!same(q, core)) break; q = fresh(g, core); }
    if (same(q, core)) break;
    core.push(q);
  }
  let review = null;
  // The memory check can come from any module the student has mastered, in any course, so
  // old skills keep resurfacing where they are least expected. Nearer modules in the same
  // course are more likely, but nothing mastered is ever out of the pool.
  const inCourse = MODULES.filter((m) => m.courseId === mod.courseId && m.order < mod.order && masteredIds.includes(m.id));
  const anywhere = MODULES.filter((m) => m.id !== mod.id && masteredIds.includes(m.id));
  // The memory check favors the mastered modules a student has missed most lately (options.missed: id to miss count),
  // so the alternate stack goes where it is needed; otherwise nearer modules in the same course are more likely.
  const missed = anywhere.filter((m) => (options.missed || {})[m.id] > 0);
  const earlierMastered = missed.length && rng() < 0.6 ? missed : inCourse.length && rng() < 0.6 ? inCourse : anywhere;
  let review2 = null;
  if (CONFIG.REVIEW_QUESTIONS_PER_ATTEMPT > 0 && earlierMastered.length > 0) {
    const rm = pick(rng, earlierMastered);
    review = { moduleId: rm.id, question: fresh(pick(rng, rm.generators), []) };
    // A second check, from a different passed module when there is one, so two old skills
    // resurface in every round rather than one.
    const others = anywhere.filter((m) => m.id !== rm.id);
    if (CONFIG.REVIEW_QUESTIONS_PER_ATTEMPT > 1 && others.length > 0) {
      const rm2 = pick(rng, others);
      review2 = { moduleId: rm2.id, question: fresh(pick(rng, rm2.generators), []) };
    }
  }
  return { moduleId, seed, core, review, review2, dose };
}

// The prompts a student met in their last rounds on a module (and, for memory checks, on any module).
// Misses per mastered module over the last month, for the memory check to favor.
export function recentMisses(events, days = 30) {
  const since = Date.now() - days * 24 * 3600 * 1000; const count = {};
  for (const e of events) if (e.type === 'attempt_completed' && e.at && new Date(e.at).getTime() >= since) { for (const r of (e.core || [])) if (r && r.correct === false) count[e.moduleId] = (count[e.moduleId] || 0) + 1; if (e.review && e.review.correct === false) count[e.review.moduleId] = (count[e.review.moduleId] || 0) + 1; if (e.review2 && e.review2.correct === false) count[e.review2.moduleId] = (count[e.review2.moduleId] || 0) + 1; }
  return count;
}
export function recentPrompts(events, moduleId, rounds = 2) {
  const seen = events.filter((e) => e.type === 'attempt_completed' && (!moduleId || e.moduleId === moduleId)).slice(-rounds);
  return seen.flatMap((e) => (e.core || []).map((r) => r.prompt).filter(Boolean));
}

// Decides whether a typed or tapped answer is right.
export function checkAnswer(question, given) {
  if (question.type === 'trace') {
    try { return traceMatches(question.answer, typeof given === 'string' ? JSON.parse(given) : given); } catch (e) { return false; }
  }
  if (given === null || given === undefined) return false;
  const g = String(given).trim();
  if (g === '') return false;
  if (question.type === 'number') return /^-?\d+$/.test(g) && Number(g) === Number(question.answer);
  // An order question: the student's sequence must match the answer sequence exactly. Both
  // sides travel as a joined string, so the event stores plain text like any other answer.
  if (question.type === 'order') return g === (Array.isArray(question.answer) ? question.answer.join(' | ') : question.answer);
  // A writing question is never judged here. It is pending until an educator marks it.
  if (question.type === 'writing') return false;
  return g === question.answer;
}

// Turns a finished practice set into the event that gets stored.
// Only facts are stored (what was asked, what was answered, whether it was right).
// Mastery is NOT stored here — it is computed from the facts in section 4.
// `correct` here means right FIRST TIME. Younger students retry until they get it, so
// counting every eventual success would make mastery meaningless. First-try accuracy is
// what actually tells you whether they knew it.
export function makeAttemptEvent(attempt, coreResults, reviewResult, startedAt, finishedAt, review2Result = null) {
  const coreCorrect = coreResults.filter((r) => r.correct).length;
  return {
    type: 'attempt_completed',
    at: finishedAt,
    startedAt,
    moduleId: attempt.moduleId,
    seed: attempt.seed,
    core: coreResults,
    review: reviewResult,
    review2: review2Result,
    coreCorrect,
    coreTotal: coreResults.length,
    dose: attempt.dose || 1,
  };
}

export function makeLessonViewedEvent(moduleId, at) {
  return { type: 'lesson_viewed', at, moduleId };
}

export function makeResetEvent(at) {
  return { type: 'progress_reset', at };
}

// Clears progress for ONE module only (a student just needs to redo counting).
// Like every reset, this adds a record rather than deleting one.
export function makeModuleResetEvent(moduleId, at) {
  return { type: 'module_reset', at, moduleId };
}

// ---------------------------------------------------------------------
// 4. DERIVATIONS — everything the screens and reports show comes from here
// ---------------------------------------------------------------------

// A reset does not delete history (history is never deleted). It marks a
// point in time; only events after the latest reset count as "current".
export function activeEvents(events) {
  let start = 0;
  events.forEach((e, i) => { if (e.type === 'progress_reset') start = i + 1; });
  return events.slice(start);
}

export function isMasteredAttempt(event) {
  if (event.type === 'writing_marked') return event.meets === true;
  if (event.type !== 'attempt_completed') return false;
  const rules = moduleRules(event.moduleId);
  // A triple dose holds the same bar, scaled: 4 of 5 becomes 12 of 15.
  const need = event.coreTotal && event.coreTotal !== rules.questions ? Math.ceil(rules.toMaster * event.coreTotal / rules.questions) : rules.toMaster;
  return event.coreCorrect >= need;
}
// Writing: the submission event, the mark event, and what is waiting for an educator.
export function makeWritingEvent(moduleId, prompt, text, checklist, startedAt, finishedAt) {
  return { type: 'writing_submitted', at: finishedAt, startedAt, moduleId, prompt, text: String(text || ''), checklist: checklist || [], words: String(text || '').trim().split(/\s+/).filter(Boolean).length };
}
export function makeWritingMark(moduleId, submittedAt, meets, note, at) {
  return { type: 'writing_marked', at, moduleId, submittedAt, meets: meets === true, note: String(note || '') };
}
export function pendingWritings(events) {
  const active = activeEvents(events);
  const marked = new Set(active.filter((e) => e.type === 'writing_marked').map((e) => `${e.moduleId}|${e.submittedAt}`));
  return active.filter((e) => e.type === 'writing_submitted' && !marked.has(`${e.moduleId}|${e.at}`));
}
export function writingsFor(events, moduleId) {
  const active = activeEvents(events);
  return active.filter((e) => e.type === 'writing_submitted' && e.moduleId === moduleId).map((sub) => ({ ...sub, mark: active.find((e) => e.type === 'writing_marked' && e.moduleId === moduleId && e.submittedAt === sub.at) || null }));
}

export function deriveProgress(events) {
  const active = activeEvents(events);
  // When was each module last reset on its own? Anything at or before that is ignored for that module.
  const moduleResetAt = {};
  for (const e of active) if (e.type === 'module_reset') moduleResetAt[e.moduleId] = e.at;
  const perModule = {};
  for (const m of MODULES) {
    perModule[m.id] = {
      attempts: 0, lessonViews: 0, mastered: false, masteredAt: null, bestCore: 0,
      coreCorrect: 0, coreTotal: 0, firstAttemptAt: null, lastAttemptAt: null,
      // Mastery v2: a pass is a round that met the bar. The first pass unlocks the next
      // module. The star (mastered) needs a second pass on a different day.
      passes: 0, passDays: [], passed: false, firstPassedAt: null, placed: false,
    };
  }
  const review = { asked: 0, correct: 0 };
  for (const e of active) {
    if (e.type === 'placed') { for (const id of e.moduleIds || []) { const pm = perModule[id]; if (pm && !(moduleResetAt[id] && String(e.at) <= String(moduleResetAt[id]))) { pm.passed = true; pm.placed = true; } } continue; }
    const p = perModule[e.moduleId];
    if (!p) continue;
    if (moduleResetAt[e.moduleId] && String(e.at) <= String(moduleResetAt[e.moduleId])) continue; // cleared by a module reset
    if (e.type === 'writing_submitted') { p.attempts += 1; p.firstAttemptAt = p.firstAttemptAt || e.at; p.lastAttemptAt = e.at; p.pendingWriting = true; continue; }
    if (e.type === 'writing_marked') {
      p.pendingWriting = false;
      if (e.meets) { p.passes += 1; p.passed = true; p.firstPassedAt = p.firstPassedAt || e.at; const day = localDay(e.at); if (!p.passDays.includes(day)) p.passDays.push(day); if (!p.mastered && (isBeforeMasteryV2(e.at) || p.passDays.length >= 2)) { p.mastered = true; p.masteredAt = e.at; } }
      continue;
    }
    if (e.type === 'lesson_viewed') p.lessonViews += 1;
    if (e.type === 'attempt_completed') {
      p.attempts += 1;
      p.coreCorrect += e.coreCorrect;
      p.coreTotal += e.coreTotal;
      p.bestCore = Math.max(p.bestCore, e.coreCorrect);
      p.firstAttemptAt = p.firstAttemptAt || e.at;
      p.lastAttemptAt = e.at;
      if (isMasteredAttempt(e)) {
        p.passes += 1;
        p.passed = true;
        p.firstPassedAt = p.firstPassedAt || e.at;
        const day = localDay(e.at);
        if (!p.passDays.includes(day)) p.passDays.push(day);
        // Passes before the change to spaced mastery, and passes whose time cannot be read,
        // count in full: nobody loses a star they earned under the old rule.
        if (!p.mastered && (isBeforeMasteryV2(e.at) || p.passDays.length >= 2)) { p.mastered = true; p.masteredAt = e.at; }
      }
      if (e.review) { review.asked += 1; if (e.review.correct) review.correct += 1; }
      if (e.review2) { review.asked += 1; if (e.review2.correct) review.correct += 1; }
    }
  }
  const masteredIds = MODULES.filter((m) => perModule[m.id].mastered).map((m) => m.id);
  const passedIds = MODULES.filter((m) => perModule[m.id].passed).map((m) => m.id);
  const unlockedIds = [...new Set(active.filter((e) => e.type === 'module_unlocked').map((e) => e.moduleId))];
  return { perModule, review, masteredIds, passedIds, unlockedIds };
}

// ---------------------------------------------------------------------
// CUMULATIVE CHECKPOINT
// After every fourth module a student passes, the next thing offered is a checkpoint: eight
// questions drawn from everything they have passed, with nothing new in it. It is not a
// round of any module. A miss lowers that module's confidence (it counts like a missed
// memory check) and marks the module as worth a refresher on the overview. It never removes
// a pass or a star.
// ---------------------------------------------------------------------
export const CHECKPOINT_EVERY = 4;
export const CHECKPOINT_QUESTIONS = 8;
export function checkpointDue(events) {
  const progress = deriveProgress(events);
  const count = progress.passedIds.length;
  if (count < CHECKPOINT_EVERY || count % CHECKPOINT_EVERY !== 0) return null;
  const done = activeEvents(events).some((e) => e.type === 'checkpoint_completed' && e.atCount === count);
  return done ? null : { atCount: count };
}
export function buildCheckpoint(events, seed) {
  const rng = makeRng(seed);
  const progress = deriveProgress(events);
  const pool = MODULES.filter((m) => progress.passedIds.includes(m.id));
  if (pool.length === 0) return null;
  const order = shuffle(rng, pool);
  const core = [];
  for (let i = 0; i < CHECKPOINT_QUESTIONS; i++) {
    const m = order[i % order.length];
    let q = generateQuestion(pick(rng, m.generators), randInt(rng, 1, 2147483646));
    for (let tries = 0; tries < 40 && core.some((c) => questionKey(c) === questionKey(q)); tries++) q = generateQuestion(pick(rng, m.generators), randInt(rng, 1, 2147483646));
    if (core.some((c) => questionKey(c) === questionKey(q))) continue; // never a repeat (pass HR): skip the slot instead
    core.push({ ...q, fromModuleId: m.id });
  }
  return { checkpoint: true, moduleId: core[0].fromModuleId, seed, core, review: null, review2: null, atCount: progress.passedIds.length };
}
export function makeCheckpointEvent(checkpoint, results, startedAt, finishedAt) {
  return {
    type: 'checkpoint_completed',
    at: finishedAt,
    startedAt,
    atCount: checkpoint.atCount,
    results: results.map((r, i) => ({ ...r, moduleId: checkpoint.core[i].fromModuleId })),
    correct: results.filter((r) => r.correct).length,
    total: results.length,
  };
}
// Modules missed in the most recent checkpoint and not passed again since: worth a refresher.
export function refresherIds(events) {
  const active = activeEvents(events);
  const last = [...active].reverse().find((e) => e.type === 'checkpoint_completed');
  if (!last) return [];
  const missed = [...new Set((last.results || []).filter((r) => !r.correct).map((r) => r.moduleId))];
  const passedSince = new Set(active.filter((e) => e.type === 'attempt_completed' && String(e.at) > String(last.at) && isMasteredAttempt(e)).map((e) => e.moduleId));
  return missed.filter((id) => !passedSince.has(id));
}
export function checkpointSummary(events) {
  const done = activeEvents(events).filter((e) => e.type === 'checkpoint_completed');
  if (!done.length) return null;
  const last = done[done.length - 1];
  return { count: done.length, lastAt: last.at, lastCorrect: last.correct, lastTotal: last.total, missed: refresherIds(events) };
}

// ---------------------------------------------------------------------
// PLACEMENT CHECK
// A new reader can find their starting point in a subject instead of beginning at the
// bottom of their band. The check walks up one grade at a time: a probe of four questions
// from that grade's modules, three right to clear it, stop at the first grade not cleared.
// The student starts at that grade, and every module in the cleared grades is unlocked by a
// 'placed' event. Placed modules count as passed for gating and never as mastered; the star
// still has to be earned, and memory checks will visit them like any passed module.
// ---------------------------------------------------------------------
export const PLACEMENT_PROBE = 4;
export const PLACEMENT_TO_CLEAR = 3;
export function placementGrades(subject, level) {
  const band = levelFor(level);
  const grades = gradesWithCourses().filter((g) => (!band || band.grades.includes(g)) && COURSES.some((c) => c.grade === g && c.subject === subject && !c.readAloud && !c.startsHidden));
  return grades;
}
// Every grade a placement can land on, in order, whatever the band: a high school student who
// cannot clear grade 9 walks down to find where they are.
export function placementGradesAll(subject) {
  return gradesWithCourses().filter((g) => COURSES.some((c) => c.grade === g && c.subject === subject && !c.readAloud && !c.startsHidden));
}
export function buildPlacementProbe(subject, grade, seed) {
  const rng = makeRng(seed);
  const pool = MODULES.filter((m) => { const c = getCourse(m.courseId); return c && c.grade === grade && c.subject === subject; });
  if (!pool.length) return null;
  const order = shuffle(rng, pool);
  const core = [];
  for (let i = 0; i < PLACEMENT_PROBE; i++) {
    const m = order[i % order.length];
    let q = generateQuestion(pick(rng, m.generators), randInt(rng, 1, 2147483646));
    for (let tries = 0; tries < 40 && core.some((c) => questionKey(c) === questionKey(q)); tries++) q = generateQuestion(pick(rng, m.generators), randInt(rng, 1, 2147483646));
    if (core.some((c) => questionKey(c) === questionKey(q))) continue; // never a repeat (pass HR): skip the slot instead
    core.push({ ...q, fromModuleId: m.id });
  }
  return { placement: true, subject, grade, moduleId: core[0].fromModuleId, seed, core, review: null, review2: null };
}
export function placementCleared(results) { return results.filter((r) => r.correct).length >= PLACEMENT_TO_CLEAR; }
// After the walk: which grade to start at, which modules are unlocked, which courses to switch on.
export function placementOutcome(subject, level, clearedGrades, startGradeGiven = null) {
  const all = placementGradesAll(subject);
  const grades = placementGrades(subject, level);
  const startGrade = startGradeGiven || grades.find((g) => !clearedGrades.includes(g)) || grades[grades.length - 1];
  // Everything below the starting grade is placed past, whether it was probed or sits under a cleared grade.
  const below = all.slice(0, all.indexOf(startGrade));
  const clearedModuleIds = MODULES.filter((m) => { const c = getCourse(m.courseId); return c && c.subject === subject && (below.includes(c.grade) || clearedGrades.includes(c.grade)); }).map((m) => m.id);
  const startCourseIds = COURSES.filter((c) => c.subject === subject && c.grade === startGrade).map((c) => c.id);
  return { startGrade, clearedModuleIds, startCourseIds };
}
export function makePlacementEvent(subject, startGrade, clearedModuleIds, at) {
  return { type: 'placed', at, subject, startGrade, moduleIds: clearedModuleIds };
}
// An educator can open a locked module by hand. The algorithm advises; the educator decides.
export function makeUnlockEvent(moduleId, at) { return { type: 'module_unlocked', at, moduleId }; }

export function placementDone(events, subject) {
  return activeEvents(events).some((e) => e.type === 'placed' && e.subject === subject && !e.quickCheck);
}

// ---------------------------------------------------------------------
// THE QUICK CHECK: "I already know this"
// Placement settles the grade; this settles one module inside it. The next available module
// (never a locked one, never one already tried) offers five questions, one from each of its
// generator slots, with no lesson first. Pass at the module's own mark and the module is placed
// through the same 'placed' event placement uses, so gating, the report, the transcript and the
// memory checks all already know what that means: passed for gating, never mastered by the check,
// the star still to be earned, and memory checks keep visiting it. A miss records the try and
// opens the lesson; it never counts toward a loop back, because a student who tried to skip has
// not yet tried to learn. Three answers in under two seconds mean nobody read the questions, and
// such a check does not place whatever the score. Spoken courses and Writing never offer it.
// ---------------------------------------------------------------------
export const QUICK_CHECK_QUESTIONS = 5;
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
function niceDate(iso) { const d = new Date(iso); return isNaN(d) ? String(iso).slice(0, 10) : `${MONTHS_LONG[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`; }
export function buildQuickCheck(moduleId, seed) {
  const m = getModule(moduleId); if (!m) return null;
  const rng = makeRng(seed);
  const core = [];
  for (let i = 0; i < QUICK_CHECK_QUESTIONS; i++) {
    const genId = m.generators[i % m.generators.length];
    let q = generateQuestion(genId, randInt(rng, 1, 2147483646));
    for (let tries = 0; tries < 12 && core.some((c) => questionKey(c) === questionKey(q)); tries++) q = generateQuestion(genId, randInt(rng, 1, 2147483646));
    core.push({ ...q, fromModuleId: m.id });
  }
  return { quickCheck: true, moduleId: m.id, seed, core, review: null, review2: null };
}
export function quickCheckAllowed(events, moduleId) {
  const m = getModule(moduleId); if (!m) return false;
  const course = getCourse(m.courseId);
  if (!course || course.readAloud || course.subject === 'Writing') return false;
  if (activeEvents(events).some((e) => (e.type === 'attempt_completed' || e.type === 'quick_check') && e.moduleId === moduleId)) return false;
  const p = deriveProgress(events).perModule[moduleId];
  return !!p && !p.mastered && !p.passed && !p.placed;
}
export function quickCheckOutcome(moduleId, results) {
  const right = results.filter((r) => r.correct).length;
  const rushed = results.filter((r) => typeof r.timeMs === 'number' && r.timeMs < 2000).length;
  const guessed = rushed >= 3;
  // A quick check is always five questions, so it passes at four of five whatever the module's round size is.
  const need = Math.max(1, Math.round(QUICK_CHECK_QUESTIONS * CONFIG.MASTERY_MIN_CORRECT / CONFIG.CORE_QUESTIONS_PER_ATTEMPT));   // four of five
  return { right, total: results.length, guessed, passed: right >= need && !guessed };
}
export function makeQuickCheckEvent(moduleId, results, at) {
  const o = quickCheckOutcome(moduleId, results);
  return { type: 'quick_check', at, moduleId, right: o.right, total: o.total, guessed: o.guessed, passed: o.passed };
}
export function makeQuickPlacedEvent(moduleId, at) {
  const m = getModule(moduleId);
  return { type: 'placed', at, subject: getCourse(m.courseId).subject, startGrade: null, moduleIds: [moduleId], quickCheck: true };
}

