export function experimentsFor(grade) { return EXPERIMENTS[grade] || []; }

// ---------------------------------------------------------------------
// DAYS OF REMEMBRANCE. On a few days each year, schools across the United States pause to
// remember. The app shows one quiet card that day, the same words for every age, and an
// educator can hide it on this device for the year. Nothing is recorded about it.
// Memorial Day is the last Monday of May; the others are fixed dates.
// ---------------------------------------------------------------------
export const REMEMBRANCE_DAYS = [
  // The words are Mikey's (2026-09-23); each line is one paragraph on the card.
  { id: 'september-11', title: 'September 11', when: (y, m, d) => m === 9 && d === 11, lines: [
    'On this day in 2001, nearly three thousand people were killed in attacks on New York City, the Pentagon, and in a field near Shanksville, Pennsylvania.',
    'Firefighters, police officers and ordinary people ran toward the danger to help and many of them did not come home.',
    'Every year, on this day, our country pauses to remember them.',
    'Take a quiet moment before you begin today. Think about the people, their families and even your own. Cherish the moments with those closest to you because, at the end of the day, this is what life is all about.',
  ] },
  { id: 'veterans-day', title: 'Veterans Day', when: (y, m, d) => m === 11 && d === 11, lines: [
    'Today is Veterans Day. On this day, at eleven in the morning on November 11, 1918, World War 1 had ended.',
    'Veterans Day honors everyone, and their families, who have served in the armed forces of the United States whether it be in war or in peace.',
    'If you know someone who has served in the armed forces, today is a good day to say thank you.',
    'Take a quiet moment before you begin.',
  ] },
  { id: 'memorial-day', title: 'Memorial Day', when: (y, m, d) => m === 5 && d > 24 && new Date(y, 4, d).getDay() === 1, lines: [
    'Today is Memorial Day. It is set aside for the people who have died serving in the armed forces of the United States. We honor and remember every member from the first wars all the way up to the present.',
    'Flags fly at half-staff until noon and many families will visit the graves of loved ones to honor them and leave flowers.',
    'Today is a day for remembering more than celebrating.',
    'Take a quiet moment before you begin.',
  ] },
];
export function remembranceFor(isoLocalDate) {
  const parts = String(isoLocalDate || '').split('-').map(Number);
  if (parts.length < 3 || parts.some((n) => !Number.isFinite(n))) return null;
  const [y, m, d] = parts;
  return REMEMBRANCE_DAYS.find((day) => day.when(y, m, d)) || null;
}
export function isRemembranceDay(isoLocalDate) { return remembranceFor(isoLocalDate) !== null; }
export const REMEMBRANCE = REMEMBRANCE_DAYS[0];

// Spaced mastery began on this day. A pass on an earlier day, or with a time that cannot
// be read, earns the star on its own, as it did then.
export const MASTERY_V2_FROM = '2026-09-14';
function isBeforeMasteryV2(at) {
  const d = new Date(at);
  if (Number.isNaN(d.getTime())) return true;
  return localDay(at) < MASTERY_V2_FROM;
}
function localDay(at) {
  const d = new Date(at);
  if (Number.isNaN(d.getTime())) return String(at);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
// What a finished round meant for this module: the star, a first pass, a repeat on the same
// day, or not yet. The result screen and the reports speak from this.
export function masteryState(events, moduleId) {
  const p = deriveProgress(events).perModule[moduleId];
  if (!p) return 'not-yet';
  if (p.mastered) return 'mastered';
  if (p.passed) return 'passed';
  return 'not-yet';
}

// A module is 'mastered', 'available' (the first module, or the one right after
// a mastered module), or 'locked'. A locked module cannot be opened.
// Everything a module needs mastered first: the module before it in its own course, and
// any module it names in `requires`, which may live in another course or another grade.
// This is the dependency graph. It is what stops a student meeting fractions before they
// can count, and it is what loop-back routing walks down when they struggle.
export function prerequisitesOf(moduleId) {
  const mod = getModule(moduleId);
  if (!mod) return [];
  const course = getCourse(mod.courseId);
  // Most courses are a chain: each module needs the one before it. A course marked
  // linear: false is a set of parallel activities (pre-K), where only named prerequisites count.
  const sorted = [...course.modules].sort((a, b) => a.order - b.order);
  const i = sorted.findIndex((m) => m.id === moduleId);
  const inCourse = course.linear !== false && i > 0 ? [sorted[i - 1].id] : [];
  return [...new Set([...inCourse, ...(mod.requires || [])])];
}

// ---------------------------------------------------------------------
// LOOP-BACK ROUTING
// When a student keeps missing a module, the problem is often further back than the
// module itself. After two failed rounds the platform reopens the prerequisite for a
// quick check, even if it was mastered before. That check must be passed again before
// the student returns. This is how a fifth grader struggling with fractions ends up
// briefly back in third-grade division, and comes back up with the gap closed.
// ---------------------------------------------------------------------
export const LOOP_BACK_AFTER = 2; // failed rounds in a row before we look further back

// The failed rounds on a module since it was last passed, counting back from the latest.
export function failedStreak(events, moduleId) {
  const active = activeEvents(events).filter((e) => e.type === 'attempt_completed' && e.moduleId === moduleId);
  let n = 0;
  for (let i = active.length - 1; i >= 0; i--) { if (isMasteredAttempt(active[i])) break; n++; }
  return n;
}

// Does this module need a loop back right now, and to where? Returns the prerequisite to
// revisit, or null. The most recent prerequisite in the chain is the first suspect.
export function loopBackTarget(events, moduleId) {
  if (failedStreak(events, moduleId) < LOOP_BACK_AFTER) return null;
  const prereqs = prerequisitesOf(moduleId);
  if (prereqs.length === 0) return null;
  // Do not send them back again if the prerequisite has already been re-passed since the failures began.
  const active = activeEvents(events);
  const lastFail = [...active].reverse().find((e) => e.type === 'attempt_completed' && e.moduleId === moduleId);
  const target = prereqs[prereqs.length - 1];
  const rePassed = active.some((e) => e.type === 'attempt_completed' && e.moduleId === target && isMasteredAttempt(e) && lastFail && String(e.at) > String(lastFail.at));
  return rePassed ? null : target;
}

// Recorded when a loop back happens, so the educator can see it on the report.
export function makeLoopBackEvent(fromModuleId, toModuleId, at) {
  return { type: 'looped_back', at, moduleId: fromModuleId, toModuleId };
}

// A module is open when every prerequisite is mastered. There is no other way in.
// Which prerequisites actually gate a module for this student. Those inside the same
// course always do. One from another course only does when that course is assigned:
// an educator who places a student at grade 3 without grade 2 has judged them past it,
// and grade 3 must open. Loop-back still uses the full list, so a struggling student is
// sent back to the earlier module all the same.
export function gatingPrerequisites(moduleId, enabledIds) {
  const all = prerequisitesOf(moduleId);
  if (!enabledIds) return all;
  const mod = getModule(moduleId);
  return all.filter((id) => { const p = getModule(id); return !p || p.courseId === mod.courseId || enabledIds.includes(p.courseId); });
}

export function moduleStatuses(progress, enabledIds) {
  return MODULES.map((m) => {
    if (progress.perModule[m.id].mastered) return { id: m.id, status: 'mastered' };
    if (progress.perModule[m.id].passed) return { id: m.id, status: 'passed' }; // unlocked the next module; the star waits for another day
    if (progress.unlockedIds.includes(m.id)) return { id: m.id, status: 'available' }; // an educator opened it by hand
    const ready = gatingPrerequisites(m.id, enabledIds).every((id) => progress.perModule[id] && progress.perModule[id].passed);
    return { id: m.id, status: ready ? 'available' : 'locked' };
  });
}

// Walks the graph to make sure it is one: every named prerequisite exists, and no module
// requires itself through any chain. The tests call this; a cycle would lock a student out
// of a module forever, so it must never ship.
export function checkPrerequisiteGraph() {
  const problems = [];
  const ids = new Set(MODULES.map((m) => m.id));
  for (const m of MODULES) for (const r of m.requires || []) if (!ids.has(r)) problems.push(`${m.id} requires ${r}, which does not exist`);
  const visiting = new Set(); const done = new Set();
  const visit = (id, trail) => {
    if (done.has(id)) return;
    if (visiting.has(id)) { problems.push(`cycle: ${[...trail, id].join(' -> ')}`); return; }
    visiting.add(id);
    for (const r of prerequisitesOf(id)) if (ids.has(r)) visit(r, [...trail, id]);
    visiting.delete(id); done.add(id);
  };
  for (const m of MODULES) visit(m.id, []);
  return problems;
}

// Which courses an educator has switched on for this learner. With no setting, all courses are on.
// Stored as an event like everything else, so the history of who enabled what is kept.
export function makeCoursesEnabledEvent(courseIds, at) {
  return { type: 'courses_enabled', at, courseIds: [...courseIds] };
}
// Teacher notes live on the student's log as events, so they ride along in every backup and
// survive a reset like the course settings do. A removed note stays in the log, hidden.
// A coloring break leaves a note of when and which picture: never a score, never on the transcript,
// but an educator wondering where the time went should be able to see it.
export function makeColoredEvent(picture, at) { return { type: 'colored', at, picture }; }
// A story opened by a student, once per module: the report can say which stories, and which of the
// cast, a child has met. Nothing about the child is kept, only that the story was opened.
export function makeStoryReadEvent(moduleId, at) { return { type: 'story_read', at, moduleId }; }
export function storiesRead(events) {
  const seen = new Map();
  for (const e of events) if (e.type === 'story_read' && !seen.has(e.moduleId)) seen.set(e.moduleId, e.at);
  return [...seen.entries()].map(([moduleId, at]) => ({ moduleId, at }));
}
export function coloringBreaks(events) { return activeEvents(events).filter((e) => e.type === 'colored').length; }
export function makeNoteEvent(text, at) { return { type: 'note', at, noteId: `n_${at}`, text: String(text).trim() }; }
export function makeNoteRemovedEvent(noteId, at) { return { type: 'note_removed', at, noteId }; }
export function teacherNotes(events) {
  const removed = new Set(events.filter((e) => e.type === 'note_removed').map((e) => e.noteId));
  return events.filter((e) => e.type === 'note' && e.text && !removed.has(e.noteId)).map((e) => ({ id: e.noteId, at: e.at, text: e.text })).sort((a, b) => (a.at < b.at ? 1 : -1));
}
// The sentence in a module's lesson that says a worded answer, so a wrong answer can point back to
// where it was taught. Null for computed answers and for anything the lesson never said.
export function taughtLine(moduleId, answer) {
  const m = getModule(moduleId); if (!m || typeof answer !== 'string' || /\d/.test(answer) || /^[a-z]+:/.test(answer)) return null;
  const want = answer.toLowerCase().replace(/[.!]$/, '');
  const pool = [...m.lesson.paragraphs, m.lesson.keyIdea, ...(m.lesson.script || []).map((x) => x.say)].join(' ').replace(/\[\[|\]\]|\*\*/g, '');
  return pool.split(/(?<=[.!?])\s+/).find((sent) => sent.toLowerCase().includes(want)) || null;
}
// A grade is complete when every module of every course the student was given in that grade is
// mastered, placed past, or passed on its quick check. Courses never switched on are not required,
// so a student who skipped a course through placement still finishes the grade.
export function gradeCompleted(events, grade, courseIds) {
  const per = deriveProgress(events).perModule; const active = activeEvents(events);
  const quickPassed = new Set(active.filter((e) => e.type === 'quick_check' && e.passed).map((e) => e.moduleId));
  const courses = COURSES.filter((c) => c.grade === grade && courseIds.includes(c.id) && c.modules.length);
  return courses.length > 0 && courses.every((c) => c.modules.every((m) => { const pm = per[m.id] || {}; return pm.mastered || pm.placed || quickPassed.has(m.id); }));
}
export function completedGrades(events) { const ids = enabledCourseIds(events); return GRADES.filter((g) => gradeCompleted(events, g, ids)); }
// The certificate for a grade is offered once on the student's card, then remembered as made or
// skipped; the report keeps a way back to it either way.
// When the educator last opened a student's report, kept on the roster, so the report can lead
// with what moved since then.
export function setReportSeen(roster, id, at) {
  return { ...roster, students: roster.students.map((s) => (s.id === normalizeStudentId(id) ? { ...s, reportSeenAt: at } : s)) };
}
export function changesSince(events, sinceIso) {
  const since = sinceIso ? new Date(sinceIso).getTime() : 0;
  const recent = (events || []).filter((e) => e.at && new Date(e.at).getTime() >= since);
  const attempts = recent.filter((e) => e.type === 'attempt_completed');
  const per = deriveProgress(events).perModule;
  const mastered = Object.entries(per).filter(([, p]) => p.mastered && p.masteredAt && new Date(p.masteredAt).getTime() >= since).map(([id]) => (getModule(id) || {}).title).filter(Boolean);
  return { attempts: attempts.length, questions: attempts.reduce((n, e) => n + ((e.core || []).length), 0), mastered, stories: storiesRead(events).filter((r) => new Date(r.at).getTime() >= since).length, colored: recent.filter((e) => e.type === 'colored').length };
}
export function setCertificateState(roster, id, grade, state) {
  return { ...roster, students: roster.students.map((s) => (s.id === normalizeStudentId(id) ? { ...s, certificates: { ...(s.certificates || {}), [grade]: state } } : s)) };
}
export function certificatesPending(student, grades) { return grades.filter((g) => !((student && student.certificates) || {})[g]); }
export function enabledCourseIds(events) {
  let ids = COURSES.map((c) => c.id);
  for (const e of events) if (e.type === 'courses_enabled') ids = e.courseIds.filter((id) => getCourse(id));
  return ids;
}

// The confidence score (1–5). It answers "did they pass by understanding, or by luck?"
// The rules are listed in CONFIDENCE_RULES and printed on every report, so the
// score is never a black box. Time signals are only used when timings exist.
export const CONFIDENCE_RULES = [
  'Confidence starts at 1 for any module that has been practiced.',
  `+2 if the module is mastered (${CONFIG.MASTERY_MIN_CORRECT} or more of ${CONFIG.CORE_QUESTIONS_PER_ATTEMPT} correct in one set).`,
  '+1 if the most recent practice set was perfect.',
  '+1 if the last 8 or more core answers in this module were all correct, OR at least 2 review questions from this module have been asked and 80% or more were correct.',
  'The highest score is 5. "Guessing?" is shown when 2 or more answers in the latest set were wrong in under 4 seconds.',
];

function median(numbers) {
  const a = [...numbers].sort((x, y) => x - y);
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}

export function computeConfidence(moduleId, events) {
  const active = activeEvents(events);
  const attempts = active.filter((e) => e.type === 'attempt_completed' && e.moduleId === moduleId);
  if (attempts.length === 0) return { score: null, signals: [], streak: 0, medianSec: null, reviewsAsked: 0, reviewsCorrect: 0 };
  const latest = attempts[attempts.length - 1];
  const signals = [];
  let score = 1;
  if (attempts.some(isMasteredAttempt)) { score += 2; signals.push('mastered'); }
  if (latest.coreCorrect === latest.coreTotal) { score += 1; signals.push('latest set perfect'); }
  const answers = attempts.flatMap((e) => e.core);
  let streak = 0;
  for (let i = answers.length - 1; i >= 0 && answers[i].correct; i--) streak += 1;
  const reviews = active.filter((e) => e.type === 'attempt_completed').flatMap((e) => [e.review, e.review2].filter((r) => r && r.moduleId === moduleId))
    .concat(active.filter((e) => e.type === 'checkpoint_completed').flatMap((e) => (e.results || []).filter((r) => r.moduleId === moduleId)));
  const reviewsCorrect = reviews.filter((r) => r.correct).length;
  const retentionStrong = reviews.length >= 2 && reviewsCorrect / reviews.length >= 0.8;
  if (streak >= 8) signals.push(`${streak} correct in a row`);
  if (retentionStrong) signals.push(`review ${reviewsCorrect} of ${reviews.length} correct`);
  if (streak >= 8 || retentionStrong) score += 1;
  // Missing the material when it comes back, in a memory check or a checkpoint, costs a point.
  const retentionWeak = reviews.length >= 1 && reviewsCorrect / reviews.length <= 0.5;
  if (retentionWeak) { score -= 1; signals.push(`missed ${reviews.length - reviewsCorrect} of ${reviews.length} when it came back`); }
  score = Math.max(1, Math.min(5, score));
  const fastWrong = latest.core.filter((r) => !r.correct && typeof r.timeMs === 'number' && r.timeMs < 4000).length;
  if (fastWrong >= 2) signals.push('guessing?');
  const times = answers.map((r) => r.timeMs).filter((t) => typeof t === 'number' && t >= 0);
  const medianSec = times.length ? Math.round(median(times) / 100) / 10 : null;
  return { score, signals, streak, medianSec, reviewsAsked: reviews.length, reviewsCorrect };
}

// The progress report. Every number here is recomputed from the event log
// each time, and the report carries its own definitions so a reader knows
// exactly what each number means.
// Plain-language definitions for the educator report. Written for someone who does
// not work in technology: every term the page uses, explained in ordinary sentences.
export const EXPLANATIONS = [
  {
    term: 'Practiced',
    plain: 'When a student opens a module and clicks through all available questions, they have practiced it. They can practice any module as often as they like and expect fresh sets of questions and answers as they go. The more they practice, the more opportunities we have to introduce questions from prior modules as a form of memory check. These old questions do not count against their mastery of the current module.',
  },
  {
    term: 'Mastered',
    plain: 'A module is passed once a student answers a pre-determined number of questions correctly (depending on the grade and subject matter) within a single session. One session, rather than patching several attempts together, because a student either has it or does not on the day. A pass opens the next module right away. Mastery, the star, takes a second pass on a different day, because doing it again after a gap is the real test of whether it stuck. Mastery is not the end of a module: its questions return later as memory checks, inside rounds from any course, so the record shows whether the learning held rather than only that it happened once.',
    plain: 'A module is considered mastered once a student answers a pre-determined number of questions correctly (depending on the grade and subject matter) within a single session. One session, rather than patching several sessions from varying days or times, shows true understanding. Until a student achieves this mastery mark, the following modules continue to remain locked. The result? No student is pushed forward without a solid understanding of the prerequisites. Mastery is not the end of a module: its questions return later as memory checks, inside rounds from any course, so the record shows whether the learning held rather than only that it happened once.',
  },
  {
    term: 'Confidence, scored 1 to 5',
    plain: 'This is our best estimate of whether or not a student truly understands a module (versus simply having a good day). Everyone starts at 1. Mastering a module adds 2 and a flawless round adds another. The last point, or a perfect confidence score, will always be the hardest to achieve. It comes either from eight correct answers in a row or from continuing to reliably answer material correctly as it reappears over time. Spaced repetition, or the re-introduction of material over increasingly lengthened periods of time, is a highly effective technique when it comes to long-term retention of information.',
  },
  {
    term: 'What holds a confidence score down',
    plain: 'A score stays low when a student has practiced a module one or more times without mastering it. A reliable way of keeping confidence down is scoring lower on consecutive attempts or not answering enough questions correctly in a row. The goal is to ensure that the information sticks. If two or more wrong answers come back in under four seconds, the progress report adds a note that says "guessing?" This is because answering quickly usually indicates tapping rather than thinking. Missing a question from the module when it comes back, in a memory check or a checkpoint, also costs a point, because the score is meant to say whether it stuck.',
  },
  {
    term: 'Answered correctly',
    plain: 'Out of every question answered within a module, this is the share they get right. It includes the shaky attempts, the perfect ones and everything in between. This creates a fair picture of the entire journey rather than relying only on "mastered."',
  },
  {
    term: 'Typical answering time',
    plain: 'Every student answers questions at a pace that is unique to them. We use these individualized times to work out what is typical then watch for answers that arrive significantly faster or slower. Alongside the confidence score, this timing tells you a great deal. Quick and correct equals fluency while quick and incorrect might mean guessing.',
  },
  {
    term: 'Not assigned',
    plain: "A course and its corresponding modules are switched off and hidden from the student. They do not appear for the student until assigned (different from \"Not started\").",
  },
  {
    term: 'Reflections',
    plain: 'These are the "Wonder" questions which have no right or wrong answer. They are not graded nor do they impact timing, confidence or mastery scores. The goal of these is to promote improved retention of information through story, curiosity, critical thinking and an open mind. Whatever they write is never saved for privacy compliance reasons.',
  },
];

// ---------------------------------------------------------------------
// Words for people. Two builders that turn the numbers into sentences.
// Both follow the house style: complete sentences, varied length, simple terms.
// ---------------------------------------------------------------------

// What to say to a learner when a practice round ends. Names what they just did and
// what comes next, so the screen talks to them rather than reporting on them.
export function encouragementFor(events, moduleId, mastered) {
  const mod = getModule(moduleId);
  if (!mod) return '';
  // Under spaced mastery a passing round is not always the star. Say which it was.
  if (mastered) {
    const p = deriveProgress(events).perModule[moduleId];
    if (p && p.passed && !p.mastered) {
      const inCourse0 = MODULES.filter((m) => m.courseId === mod.courseId).sort((a, b) => a.order - b.order);
      const next0 = inCourse0.find((m) => m.order === mod.order + 1);
      const opened = next0 ? `**${next0.title}** is open now.` : 'That was the last module in this course.';
      const first = `You passed **${lowerTitle(mod.title)}!** Way to go!`;
      const later = 'Come back on another day and pass it again to earn the star. Doing it again after a gap is the real test of whether it stuck.';
      if (p.passes === 1) return [first, opened, later].join('\n');
      return `Passed again! Nice work.\nA pass on a different day is what earns the star, so come back tomorrow or later this week.`;
    }
  }
  const course = getCourse(mod.courseId);
  const progress = deriveProgress(events);
  const inCourse = MODULES.filter((m) => m.courseId === mod.courseId).sort((a, b) => a.order - b.order);
  const next = inCourse.find((m) => m.order === mod.order + 1);
  const courseDone = inCourse.every((m) => progress.masteredIds.includes(m.id));
  if (!mastered) {
    const p = progress.perModule[moduleId];
    const tries = p ? p.attempts : 1;
    if (tries <= 1) return `Good first try at ${lowerTitle(mod.title)}. Let us go through it once more and then have another go.`;
    return `Don't worry, you'll get it but first, let's route back to some of the fundamentals underpinning these concepts.`;
  }
  if (courseDone) {
    const enabled = enabledCourseIds(events);
    const nextCourse = COURSES.filter((c) => enabled.includes(c.id) && c.id !== course.id)
      .find((c) => !MODULES.filter((m) => m.courseId === c.id).every((m) => progress.masteredIds.includes(m.id)));
    return nextCourse
      ? `You have mastered **${lowerTitle(course.title)}!** Way to go!\nNext we will learn about **${lowerTitle(nextCourse.title)}.**`
      : `You have mastered **${lowerTitle(course.title)}!** Way to go!\nThat was the last course for now.`;
  }
  return next
    ? `You have mastered **${lowerTitle(mod.title)}!** Way to go!\nNext up is **${lowerTitle(next.title)}.**`
    : `You have mastered **${lowerTitle(mod.title)}!** Way to go!`;
}

// The story of one module for an educator, in plain conversational sentences: how many
// times it was read and practiced, how each attempt went, whether the timing suggests
// guessing, what the platform will do about it, and where confidence stands now.
export function moduleStory(learnerName, events, moduleId) {
  const mod = getModule(moduleId);
  if (!mod) return '';
  const active = activeEvents(events);
  const resetAt = active.filter((e) => e.type === 'module_reset' && e.moduleId === moduleId).map((e) => e.at).sort().pop() || '';
  const mine = active.filter((e) => e.moduleId === moduleId && String(e.at) > resetAt);
  const reads = mine.filter((e) => e.type === 'lesson_viewed').length;
  const attempts = mine.filter((e) => e.type === 'attempt_completed');
  const name = learnerName;
  const rules = moduleRules(moduleId);

  const placedPast = active.some((e) => e.type === 'placed' && (e.moduleIds || []).includes(moduleId) && String(e.at) > resetAt);
  const pieces = writingsFor(events, moduleId).filter((w) => String(w.at) > resetAt);
  if (pieces.length) {
    const marked = pieces.filter((w) => w.mark); const met = marked.filter((w) => w.mark.meets);
    const waiting = pieces.length - marked.length;
    const metPart = `${met.length} ${met.length === 1 ? 'was' : 'were'} marked as meeting the bar`;
    const backPart = marked.length - met.length ? `, ${marked.length - met.length} sent back to try again` : '';
    const waitPart = waiting ? `, and ${waiting} ${waiting === 1 ? 'is' : 'are'} waiting for a mark` : '';
    const sizes = pieces.map((w) => `${w.words} words`).join(', ');
    return `${name} has sent ${pieces.length} ${pieces.length === 1 ? 'piece' : 'pieces'} of writing for ${lowerTitle(mod.title)} (${sizes}). ${metPart}${backPart}${waitPart}. Writing is marked by the educator, not the app, and the pieces themselves are kept in the record so they can be read again.`;
  }
  const quick = active.filter((e) => e.type === 'quick_check' && e.moduleId === moduleId && String(e.at) > resetAt).pop();
  if (quick && quick.passed) return `${name} took the quick check on ${lowerTitle(mod.title)} on ${niceDate(quick.at)} and got ${quick.right} of ${quick.total}, so the module was placed past without the lesson. It is not counted as mastered; the star is still to be earned, and memory checks will visit it.`;
  const quickNote = quick ? ` ${name} first tried the quick check on ${niceDate(quick.at)} and got ${quick.right} of ${quick.total}${quick.guessed ? ', too fast to count' : ''}, so the lesson came next.` : '';
  if (attempts.length === 0 && reads === 0 && placedPast) return `The placement check placed past ${lowerTitle(mod.title)}, so it is unlocked without a practice round. It is not counted as mastered; the star still has to be earned, and memory checks will visit it.`;
  if (attempts.length === 0 && reads === 0) return `${name} has not opened ${lowerTitle(mod.title)} yet. There is nothing to report until they do.`;
  if (attempts.length === 0) return `${name} has read the ${lowerTitle(mod.title)} lesson ${reads === 1 ? 'once' : reads + ' times'} but has not practiced it yet. Nothing counts until a practice round is finished.`;

  const times = (n) => (n === 1 ? 'once' : n === 2 ? 'twice' : `${n} times`);
  const parts = [`${name} read through this lesson ${times(reads || 1)} and practiced it ${times(attempts.length)}.${quickNote}`];
  const loops = mine.filter((e) => e.type === 'looped_back');
  if (loops.length) { const back = getModule(loops[loops.length - 1].toModuleId); parts.push(`After repeated misses, ${name} was sent back to ${back ? lowerTitle(back.title) : 'the module before'} for a quick check of the groundwork, then brought forward again.`); }

  // Each attempt in order, without turning into a table. A pass is called a pass; the star is
  // mentioned once, below, because mastery takes two passes on different days.
  attempts.forEach((a, i) => {
    const passed = a.coreCorrect >= rules.toMaster;
    const which = attempts.length === 1 ? 'the single practice attempt' : i === 0 ? 'the first attempt' : i === attempts.length - 1 ? 'the most recent attempt' : `attempt ${i + 1}`;
    if (passed) parts.push(`On ${which}, ${a.coreCorrect} out of ${a.coreTotal} were answered correctly, which is a pass.`);
    else parts.push(`On ${which}, ${a.coreCorrect} out of ${a.coreTotal} were answered correctly, which is not yet a pass, so the module stayed open for more practice.`);
  });
  const storyProgress = deriveProgress(events).perModule[moduleId];
  if (storyProgress && storyProgress.mastered && storyProgress.masteredAt) parts.push(`${storyProgress.passDays.length >= 2 ? 'Two passes on different days' : 'That pass'} earned the star on ${niceDate(storyProgress.masteredAt)}, so the content counts as mastered.`);

  // Timing: their pace on this module against their pace everywhere else.
  const answerTimes = (list) => list.flatMap((a) => (a.core || []).map((r) => r.timeMs)).filter((t) => typeof t === 'number' && t > 0);
  // The latest attempt is what matters: a fast final round after a slow first one is the guessing pattern.
  const here = answerTimes([attempts[attempts.length - 1]]);
  const everywhere = answerTimes(active.filter((e) => e.type === 'attempt_completed' && e.moduleId !== moduleId));
  const median = (list) => { if (!list.length) return null; const s2 = [...list].sort((x, y) => x - y); return s2[Math.floor(s2.length / 2)]; };
  const hereSec = median(here) !== null ? Math.round(median(here) / 100) / 10 : null;
  const usualSec = median(everywhere) !== null ? Math.round(median(everywhere) / 100) / 10 : null;
  const fastWrong = attempts.flatMap((a) => a.core || []).filter((r) => !r.correct && r.timeMs < 4000).length;
  if (hereSec !== null && usualSec !== null && hereSec < usualSec * 0.6) {
    parts.push(`The last round took about ${hereSec} seconds per question, noticeably quicker than the ${usualSec} seconds per question ${name} usually takes.`);
    if (fastWrong >= 2) parts.push('Several of those quick answers were wrong, which points to guessing rather than working the questions out.');
  } else if (hereSec !== null) {
    parts.push(`The last round took about ${hereSec} seconds per question which is a normal pace for them.`);
  }

  // What happens next, said plainly.
  const progress = deriveProgress(events);
  const p = progress.perModule[moduleId];
  const conf = computeConfidence(moduleId, events);
  const suspiciouslyQuick = hereSec !== null && usualSec !== null && hereSec < usualSec * 0.6;
  if (fastWrong >= 2 || suspiciouslyQuick || (p && p.mastered && attempts.length >= 3)) {
    parts.push('To be sure this is true mastery, questions from this module will be introduced again at a later time for further evaluation, which also refines the confidence score.');
  } else if (p && p.mastered) {
    parts.push('Questions from this module will reappear again later as a memory check which not only helps to improve retention, it refines the confidence score.');
  } else {
    parts.push(`Until ${rules.toMaster} out of ${rules.questions} is reached, the modules after this one stay locked, and every new practice round brings a fresh set of questions.`);
  }
  if (conf.score !== null) parts.push(`${name}'s confidence score in ${lowerTitle(mod.title)} currently stands at ${conf.score} out of 5.`);
  if (p && refresherIds(events).includes(moduleId)) parts.push('A question from this module was missed in the last checkpoint, so a quick refresher round is suggested before moving on. The pass and the star are kept either way.');
  if (p && p.placed && !p.mastered && p.passes === 0) parts.push('The placement check placed past this module earlier, so it was unlocked without a pass. The star still has to be earned.');
  if (p && !p.mastered && p.passed && p.firstPassedAt) parts.push(`Passed on ${new Date(p.firstPassedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}. A second pass on a different day is what earns the star, because doing it again after a gap is the real test of whether it stuck.`);
  if (p && p.mastered && p.masteredAt) parts.push(`Mastered on ${new Date(p.masteredAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} after ${attempts.length === 1 ? 'one attempt' : `${attempts.length} attempts`}.`);
  return parts.join(' ');
}

// ---------------------------------------------------------------------
// THE CLASS VIEW — every student at once, most in need first
// A teacher with twenty students wants one glance, not twenty reports. Each student
// gets a need score built from things already in their record: modules stuck on,
// loop backs, guessing flags, low confidence, and days since they last practiced.
// Higher means more in need. The reasons are listed in words so the score is never a
// mystery.
// ---------------------------------------------------------------------
// -----------------------------------------------------------------------------------------------------------------
// teachPhrase and goalPhrase (2026-10-03, pass IT, Mikey). In plain terms: a lesson title inside a sentence. "It teaches
// counting to 10" and "the goal was to learn how to count to 10", never "It teaches count to 10". A title that starts with
// a doing word is turned around (both doing words when there are two, as in Compare and contrast); a question title
// reads as it is; a sentence title takes that; any other title is a topic.
// -----------------------------------------------------------------------------------------------------------------
const TITLE_DOING = { Count: 'counting', Trace: 'tracing', Match: 'matching', Read: 'reading', Tell: 'telling', Draw: 'drawing', Find: 'finding', Compare: 'comparing', Contrast: 'contrasting', Listen: 'listening', Tap: 'tapping', Show: 'showing', Spend: 'spending', Save: 'saving', Share: 'sharing' };
const QUESTION_TITLE = /^(How|What|Why|Where|When|Which|Who)\b/;
const SENTENCE_TITLE = /^[A-Z][a-z]+(?: [a-z]+)? (is|are|was|were|has|have|need|needs|makes|make|moves|grows)\b/;
const doingOf = (w) => TITLE_DOING[w.charAt(0).toUpperCase() + w.slice(1)];
export function titleAsDoing(title) {
  const t = String(title || ''); const all = /^([A-Z][a-z]+)((?:, [a-z]+)*(?: and [a-z]+)?)$/.exec(t);
  if (all) { const words = t.match(/[A-Za-z]+/g).filter((w) => w !== 'and'); if (words.every(doingOf)) return t.replace(/[A-Za-z]+/g, (w) => (w === 'and' ? w : doingOf(w))); }
  const first = t.split(/[ ,]/)[0];
  return TITLE_DOING[first] ? TITLE_DOING[first] + t.slice(first.length) : null;
}
export function teachPhrase(title) {
  const t = String(title || ''); const doing = titleAsDoing(t);
  if (doing) return doing;
  if (SENTENCE_TITLE.test(t) && !QUESTION_TITLE.test(t)) return `that ${lowerTitle(t)}`;
  return lowerTitle(t);
}
export function goalPhrase(title) {
  const t = String(title || '');
  if (titleAsDoing(t)) return `how to ${t.charAt(0).toLowerCase()}${t.slice(1)}`;
  if (QUESTION_TITLE.test(t)) return lowerTitle(t);
  if (SENTENCE_TITLE.test(t)) return `that ${lowerTitle(t)}`;
  return `about ${lowerTitle(t)}`;
}
// The weekly note: one plain paragraph about the last seven days, the same on the report and in the
// class printout. Nothing about the student beyond what the log already holds.
export function weeklyNote(shownName, events, now) {
  const rep = buildReport(shownName, events); const week = new Date(now).getTime() - 7 * 24 * 3600 * 1000; const rows = rep.modules || [];
  const recent = (events || []).filter((e) => e.at && new Date(e.at).getTime() >= week);
  const attempts = recent.filter((e) => e.type === 'attempt_completed');
  const asked = attempts.reduce((n, e) => n + ((e.core || []).length), 0); const right = attempts.reduce((n, e) => n + (e.core || []).filter((r) => r.correct).length, 0);
  const touched = [...new Set(attempts.map((e) => (getModule(e.moduleId) || {}).title).filter(Boolean))];
  const masteredNow = rows.filter((m) => m.mastered && m.masteredAt && new Date(m.masteredAt).getTime() >= week).map((m) => m.title);
  const colored = recent.filter((e) => e.type === 'colored').length;
  const met = storiesRead(events).filter((r) => new Date(r.at).getTime() >= week).map((r) => STORY_TITLES[r.moduleId] ? { ...STORY_TITLES[r.moduleId], goal: String(r.moduleId).startsWith('course:') ? ((getCourse(r.moduleId.slice(7)) || {}).title || '') : ((getModule(r.moduleId) || {}).title || '') } : null).filter(Boolean);
  // Each lesson name sits on its own bold line (pass IT, Mikey): a list run into one sentence read the comma inside One
  // more, one less as two lessons, and the same lessons appeared twice, once as worked on and again as mastered. Now the
  // week splits into mastered this week, still practicing, and what comes next, and no lesson is named twice.
  const practicing = touched.filter((t) => !rows.some((m) => m.title === t && m.mastered));
  const next = rows.find((m) => !m.mastered && !practicing.includes(m.title));
  const bullets = (xs, cap) => [...xs.slice(0, cap).map((t) => `\n• **${t}**`), xs.length > cap ? `\n• and ${xs.length - cap} more` : ''].join('');
  const parts = [];
  parts.push(attempts.length ? ['This week ', shownName, ' answered ', String(asked), ' questions and got ', String(right), ' right.'].join('') : ['This week ', shownName, ' did not practice on this device.'].join(''));
  if (masteredNow.length) parts.push([shownName, ' mastered:', bullets(masteredNow, 8)].join(''));
  if (practicing.length) parts.push(['Still practicing:', bullets(practicing, 5)].join(''));
  if (colored) parts.push([shownName, ' colored ', colored === 1 ? 'a picture' : `${colored} pictures`, '.'].join(''));
  if (met.length) parts.push([shownName, ' read:', ...met.map((m) => ['\n• **', m.title, '**', m.about ? [', a story about ', m.about].join('') : '', '.', m.goal ? [' Through this story, the goal was to learn ', goalPhrase(m.goal), '.'].join('') : ''].join(''))].join(''));
  if (next) parts.push(`Next up: **${next.title}**.`); else if (!practicing.length) parts.push('Every assigned module is mastered.');
  return parts.join('\n\n');
}
// Story titles by module, filled by the app at start (stories live in their own file), so the note
// can name a story without logic importing it.
export const STORY_TITLES = {};   // moduleId -> { title, about }
export function classView(students, now) {
  const rows = students.map(({ id, label, events }) => {
    const report = buildReport(label || id, events);
    const active = activeEvents(events);
    const assigned = report.modules.filter((m) => report.enabledCourseIds.includes(m.courseId));
    const attempts = active.filter((e) => e.type === 'attempt_completed');
    const lastAt = attempts.length ? attempts[attempts.length - 1].at : null;
    const daysIdle = lastAt ? Math.floor((new Date(now) - new Date(lastAt)) / 86400000) : null;
    const reasons = [];
    let score = 0;

    // Stuck: a module with two or more misses in a row and no pass since.
    const stuck = assigned.filter((m) => !m.mastered && failedStreak(events, m.id) >= 2);
    const who = label || id;
    const bold = (m) => `**${titleCase(m.title)}**`;
    if (stuck.length) { score += 3 * stuck.length; reasons.push(`${who} is stuck on ${stuck.map((m) => `${bold(m)} (${failedStreak(events, m.id)} misses in a row, best score ${outOf(m.bestScore)})`).join('; ')}`); }

    // One miss is not a crisis, but it is not nothing either: the educator sees it, and sees what a second miss would bring.
    const missedOnce = assigned.filter((m) => !m.passed && !m.mastered && m.attempts > 0 && failedStreak(events, m.id) === 1);
    if (missedOnce.length) { score += 1; reasons.push(missedOnce.map((m) => { const f = fundamentalsOf(m.id); const back = f ? ', **' + titleCase(f.title) + '**' : ''; const tries = m.attempts === 1 ? 'attempt' : 'attempts'; return `${who} failed the last round of ${bold(m)} (${m.bestScore} right, ${m.attempts} ${tries}); a second miss would route them back to the fundamentals${back}`; }).join('. ')); }

    // Loop backs in the last while mean the platform already had to step in.
    const loops = active.filter((e) => e.type === 'looped_back').length;
    if (loops) { const backTo = [...new Set(active.filter((e) => e.type === 'looped_back').map((e) => getModule(e.toModuleId)).filter(Boolean).map((m) => lowerTitle(m.title)))]; const howOften = loops === 1 ? 'once' : `${loops} times`; score += 2 * loops; reasons.push(`${who} was sent back ${howOften} after repeated misses, to ${backTo.map((t) => `**${titleCase(t)}**`).join(' and ')}`); }

    // Guessing flags.
    const guessing = assigned.filter((m) => m.confidence.signals.some((x) => /guessing/.test(x)));
    if (guessing.length) { score += 2 * guessing.length; reasons.push(`There are signs of guessing in ${guessing.map(bold).join(', ')} (quick and incorrect answers, under four seconds each)`); }

    // Low confidence on mastered work suggests it may not hold.
    const shaky = assigned.filter((m) => m.mastered && m.confidence.score !== null && m.confidence.score <= 2);
    const refresh = assigned.filter((m) => m.refresher);
    if (refresh.length) { score += refresh.length; reasons.push(`Missed in the last checkpoint: ${refresh.map(bold).join(', ')} (a refresher round is suggested)`); }
    if (shaky.length) { score += shaky.length; reasons.push(`Mastered but shaky: ${shaky.map((m) => `${bold(m)} at confidence ${m.confidence.score} out of 5`).join(', ')}`); }

    // Not practicing at all.
    if (attempts.length === 0 && assigned.length) { score += 2; reasons.push(`${who} has not started`); }
    else if (daysIdle !== null && daysIdle >= 7) { score += 1 + Math.min(3, Math.floor(daysIdle / 7)); reasons.push(`It has been ${daysIdle} days since ${who} last practiced`); }

    const mastered = assigned.filter((m) => m.mastered).length;
    const passedOnce = assigned.filter((m) => m.passed && !m.mastered).length;
    const masteredPhrase = `${mastered} ${mastered === 1 ? 'module' : 'modules'} mastered` + (passedOnce ? ` and ${passedOnce} passed once` : '');
    // Among students who are fine, the one who needed more tries per mastered module comes
    // first, and the reason says so in words, so "on track" is never a flat list.
    const effort = mastered > 0 ? attempts.length / mastered : 0;
    if (score === 0 && mastered > 0) reasons.push(effort >= 2 ? `${who} is on track, but it took about ${effort.toFixed(1)} rounds per module to get there` : `${who} is on track and quick about it: about ${effort.toFixed(1)} rounds per module`);
    // Every row carries the same practice line the report summary shows, so a row never reads as if nothing happened.
    const practice = practiceLine(report);
    const triedText = practice.tried.length ? `Tried but not passed yet: ${practice.tried.map((t) => `**${t.title}** (${t.short})`).join('; ')}.` : '';
    const practiceText = practice.line ? practice.line + (triedText ? `\n${triedText}` : '') : '';
    const next = assigned.find((m) => !m.mastered && moduleStatuses(deriveProgress(events), report.enabledCourseIds).find((x) => x.id === m.id).status === 'available');
    // One sentence that squares the good news with the flags: a student who has mastered a lot
    // can still top the list, and the educator should see why without decoding it.
    const flagged = stuck.length + guessing.length + shaky.length + (loops ? 1 : 0);
    const why = score >= 5
      ? `${masteredPhrase}, but ${flagged} ${flagged === 1 ? 'thing needs' : 'things need'} attention right now, which is why ${label || id} is near the top.`
      : score >= 2 ? `${mastered} mastered so far; a couple of small flags, nothing urgent.` : '';
    return {
      id, label: label || id, score, reasons, why, practice: practiceText, nextTitle: next ? titleCase(next.title) : '', stage: currentGrade(events) ? gradeLabel(currentGrade(events)) : bandTitle(events),
      missedQuickChecks: assigned.filter((m) => m.quickCheck && !m.quickCheck.passed).length,
      note: report.notes.length ? report.notes[0].text.split('\n')[0].slice(0, 120) : '',
      weekly: weeklyNote(label || id, events, now),
      notesAll: report.notes.map((n) => n.text.split('\n')[0].slice(0, 120)),
      notesText: report.notes.map((n) => n.text).join('\n'),
      mastered, total: assigned.length,
      next: next ? next.title : null,
      daysIdle,
      band: score >= 5 ? 'needs help now' : score >= 2 ? 'keep an eye on' : 'on track',
      effort,
    };
  });
  return rows.sort((a, b) => b.score - a.score || b.effort - a.effort || a.label.localeCompare(b.label));
}

// The one-paragraph version a teacher can read in ten seconds.
export function classSummary(rows) {
  if (rows.length === 0) return 'No students yet.';
  const now = rows.filter((r) => r.band === 'needs help now');
  const eye = rows.filter((r) => r.band === 'keep an eye on');
  const fine = rows.length - now.length - eye.length;
  // The explanation, then the counts on a line of their own (the screen splits on the newline).
  const parts = ['Students on top could use a bit more guidance than those on bottom. Guessing, low confidence, failed attempts and slow progress all pushes students higher up the list.\n'];
  if (now.length) parts.push(`${now.length} ${now.length === 1 ? 'student needs' : 'students need'} help now (${now.map((r) => r.label).join(', ')}).`);
  if (eye.length) parts.push(`${eye.length} ${eye.length === 1 ? 'student' : 'students'} worth keeping an eye on.`);
  parts.push(`${fine} on track.`);
  return parts.join(' ').replace('\n ', '\n');
}

// ---------------------------------------------------------------------
// THE STUDENT'S OWN SUMMARY
// A few plain sentences for the learner: what they have achieved, what those skills
// open up, and a word that fits their recent record. Failure is framed as the place
// learning happens; a run of wins is named as a streak. Built from the same events as
// everything else, so it can never disagree with the record.
// ---------------------------------------------------------------------
export function studentSummary(events, moduleIds) {
  const active = activeEvents(events);
  const progress = deriveProgress(events);
  const mine = moduleIds.map((id) => getModule(id)).filter(Boolean);
  const mastered = mine.filter((m) => progress.masteredIds.includes(m.id));
  const rounds = active.filter((e) => e.type === 'attempt_completed' && moduleIds.includes(e.moduleId));
  const titles = (list) => list.map((m) => lowerTitle(m.title));
  const join = (arr) => (arr.length <= 1 ? arr.join('') : `${arr.slice(0, -1).join(', ')} and ${arr[arr.length - 1]}`);
  const out = [];

  // What has been achieved
  if (rounds.length === 0) {
    out.push("You haven't started a practice round yet, and that is the easiest thing in the world to fix. Open a module and try one.");
  } else if (mastered.length === 0) {
    out.push(`You've finished ${rounds.length} practice ${rounds.length === 1 ? 'round' : 'rounds'} and nothing is mastered yet, which is exactly how everyone starts.`);
  } else {
    const named = join(titles(mastered.slice(0, 3)).map((t) => `**${t}**`));
    const modulesWord = mastered.length === 1 ? 'module' : 'modules'; const roundsWord = rounds.length === 1 ? 'round' : 'rounds';
    const tail = mastered.length <= 3 ? `: ${named}.` : `, including ${named}.`;
    out.push(`You've mastered ${mastered.length} ${modulesWord} across ${rounds.length} practice ${roundsWord}${tail}`);
  }

  // What those skills open up
  const statuses = moduleStatuses(progress, enabledCourseIds(events));
  const unlocked = mine.filter((m) => !progress.masteredIds.includes(m.id) && statuses.find((x) => x.id === m.id)?.status === 'available' && prerequisitesOf(m.id).some((p) => progress.masteredIds.includes(p)));
  if (unlocked.length > 0) {
    const because = getModule(prerequisitesOf(unlocked[0].id).find((p) => progress.masteredIds.includes(p)));
    const opened = unlocked.length === 1 ? `**${lowerTitle(unlocked[0].title)}** is` : `${join(titles(unlocked.slice(0, 2)).map((t) => `**${t}**`))} are`;
    out.push(`Because you know ${lowerTitle(because.title)}, ${opened} open to you now. Each skill you master unlocks the ones that build on it.`);
  }

  // A word that fits the recent record
  let streak = 0;
  for (let i = rounds.length - 1; i >= 0; i--) { if (isMasteredAttempt(rounds[i])) streak++; else break; }
  const recent = rounds.slice(-6);
  const recentMisses = recent.filter((e) => !isMasteredAttempt(e)).length;
  const loops = active.filter((e) => e.type === 'looped_back').length;
  if (streak >= 3) out.push(`You are on a streak: ${streak} rounds mastered in a row. Keep that going while it feels easy.`);
  else if (recentMisses >= 3) out.push(`${recentMisses} of your last ${recent.length} rounds did not go your way. That is not a problem. A wrong answer shows you exactly what to learn next, which a lucky right answer never does, and the people who end up best at something are the ones who kept going through this part.`);
  else if (loops > 0) out.push(`You went back to an earlier module and came forward again. That is how strong foundations get built, and it is the smartest move a learner can make.`);
  else if (rounds.length > 0 && mastered.length > 0) out.push('Steady work like this adds up faster than it feels. Keep going!');
  return out;
}

// ---------------------------------------------------------------------
// TEACHING TEXT FORMAT
// Every lesson paragraph, key idea and explanation passes through this before it is
// shown. Hand-formatted text (already carrying newlines or [[ ]] lines) is left alone.
// Older text, written as dense paragraphs, is opened up mechanically so it follows the
// same rules everywhere: one sentence per line, every equation in bold, a sentence that is
// mostly an equation centered on its own line, and the variable x emphasized.
// This is a formatting pass, not a rewrite; the lessons themselves are being rewritten in
// the drawn-out style course by course.
// ---------------------------------------------------------------------
const EQUATION_RE = /(\(?-?[\d.]+[a-z]?\)?(?:\s*[-+×÷*\/]\s*\(?-?[\d.]+[a-z]?\)?)*\s*=\s*\(?-?[\d.]+[a-z]?\)?(?:\s*[-+×÷*\/]\s*\(?-?[\d.]+[a-z]?\)?)*)/g;
export function formatTeachingText(text) {
  const src = String(text || '');
  if (!src.trim() || src.includes('\n') || src.includes('[[') || src.includes('**')) return src;
  const sentences = src.split(/(?<=[.!?])\s+(?=[A-Z0-9"(\[])/).map((x) => x.trim()).filter(Boolean);
  const out = [];
  for (const sentence of sentences) {
    const equations = sentence.match(EQUATION_RE) || [];
    const eqs = equations.filter((e) => /\d/.test(e) && e.length >= 5);
    if (eqs.length === 1) {
      const rest = sentence.replace(eqs[0], '').replace(/[.:,;]+\s*$/, '').trim();
      // A sentence that is little more than the equation stands alone, centered.
      if (rest.split(/\s+/).filter(Boolean).length <= 2) { out.push(`[[${eqs[0].trim()}]]`); continue; }
    }
    let line = sentence;
    for (const e of eqs) line = line.replace(e, `**${e.trim()}**`);
    // the variable x, when it stands as a variable and not as a times sign
    line = line.replace(/(^|[^\d*])\bx\b(?!\s*\d)(?![^*]*\*\*)/g, (m, pre) => `${pre}**x**`);
    out.push(line);
  }
  return out.join('\n');
}

// The transcript: a record of work done, including courses that are no longer switched on.
// Courses a student never opened are left out, because an empty row proves nothing and a
// transcript should only report what actually happened. Nothing personal appears here
// beyond the school-issued identifier the school itself chose.
export function buildTranscript(learnerName, events) {
  const report = buildReport(learnerName, events);
  const courses = COURSES.map((course) => {
    const rows = report.modules.filter((m) => m.courseId === course.id);
    const touched = rows.filter((m) => m.attempts > 0 || m.mastered);
    if (touched.length === 0) return null;
    const mastered = rows.filter((m) => m.mastered);
    const dates = mastered.map((m) => m.masteredAt).filter(Boolean).sort();
    const scores = rows.filter((m) => m.confidence.score !== null).map((m) => m.confidence.score);
    return {
      id: course.id,
      title: course.title,
      subject: course.subject,
      grade: course.grade,
      label: courseLabel(course),
      complete: mastered.length === rows.length,
      stillAssigned: report.enabledCourseIds.includes(course.id),
      modulesTotal: rows.length,
      modulesMastered: mastered.length,
      startedAt: rows.map((m) => m.firstAttemptAt).filter(Boolean).sort()[0] || null,
      completedAt: mastered.length === rows.length && dates.length ? dates[dates.length - 1] : null,
      averageConfidence: scores.length ? Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10 : null,
      modules: rows.map((m) => ({ id: m.id, title: m.title, mastered: m.mastered, masteredAt: m.masteredAt, attempts: m.attempts, confidence: m.confidence.score })),
    };
  }).filter(Boolean);
  const byGrade = (a, b) => GRADES.indexOf(a.grade) - GRADES.indexOf(b.grade) || a.subject.localeCompare(b.subject);
  return {
    learnerName,
    generatedAt: new Date().toISOString(),
    completed: courses.filter((c) => c.complete).sort(byGrade),
    inProgress: courses.filter((c) => !c.complete).sort(byGrade),
    retention: report.retention,
    note: 'This record contains no personal information beyond the identifier chosen by the school. It holds no names of family members, no contact details and nothing a student has written.',
  };
}

// A paragraph an educator (or a parent) can read without decoding numbers.
// Everything in it comes from the report, so it can never disagree with the figures.
export function summaryParagraph(report) {
  const name = report.learnerName;
  const assigned = report.modules.filter((m) => report.enabledCourseIds.includes(m.courseId));
  if (assigned.length === 0) return `${name} has no courses switched on yet. Choose some below and they will appear here.`;

  // Group by grade and subject, because that is how a person describes it out loud.
  const groups = [];
  for (const m of assigned) {
    const course = getCourse(m.courseId);
    const key = `${course.grade}|${course.subject}`;
    let g = groups.find((x) => x.key === key);
    if (!g) { g = { key, grade: course.grade, subject: course.subject, total: 0, mastered: 0, confidences: [] }; groups.push(g); }
    g.total += 1;
    if (m.mastered) g.mastered += 1;
    if (m.confidence.score !== null) g.confidences.push(m.confidence.score);
  }
  groups.sort((a, b) => GRADES.indexOf(a.grade) - GRADES.indexOf(b.grade) || a.subject.localeCompare(b.subject));

  // "1 of 5 modules in Kindergarten math and 2 of 4 in third grade reading"
  const phrases = groups.map((g, i) => {
    const noun = i === 0 ? ` ${g.total === 1 ? 'module' : 'modules'}` : '';
    return `${g.mastered} of ${g.total}${noun} in ${gradeInSentence(g.grade)} ${g.subject.toLowerCase()}`;
  });
  const list = phrases.length === 1 ? phrases[0] : `${phrases.slice(0, -1).join(', ')} and ${phrases[phrases.length - 1]}`;
  let text = `${name} has mastered ${list}.`;
  // The same facts as parts, for a screen that wants a bulleted list followed by sentences.
  const parts = { lead: `${name} has mastered:`, items: groups.map((g) => `${g.mastered} of ${g.total} in ${gradeInSentence(g.grade)} ${g.subject.toLowerCase()}`), rest: '' };

  // How sure we are, described the way a teacher would say it rather than as a number.
  const strong = groups.filter((g) => g.confidences.length && g.confidences.reduce((a, b) => a + b, 0) / g.confidences.length >= 4);
  const building = groups.filter((g) => g.confidences.length && g.confidences.reduce((a, b) => a + b, 0) / g.confidences.length < 3);
  if (strong.length) text += ` Confidence is strongest in ${strong.map((g) => `${gradeInSentence(g.grade)} ${g.subject.toLowerCase()}`).join(' and ')}.`;
  if (building.length) text += ` There is still ground to make up in ${building.map((g) => `${gradeInSentence(g.grade)} ${g.subject.toLowerCase()}`).join(' and ')}.`;
  if (!strong.length && !building.length && groups.some((g) => g.confidences.length)) text += ' Confidence is steady across the board so far.';
  if (!groups.some((g) => g.confidences.length)) text += ' There has not been enough practice yet to say much about confidence.';

  // Practice so far: rounds, passes, and anything tried but not passed yet, named with its best score.
  const practice = practiceLine(report);
  if (practice.line) text += ` ${practice.line}`;
  if (practice.tried.length) text += ` Tried but not passed yet: ${practice.tried.map((t) => `${t.title} (${t.detail})`).join('; ')}.`;
  parts.tried = practice.tried;

  // Reflections, in words rather than a fraction.
  if (report.reflectionsAvailable > 0) {
    if (report.reflections === 0) text += ' No reflection questions have been answered yet.';
    else if (report.reflections >= report.reflectionsAvailable) text += ' Every reflection has been completed.';
    else text += ` ${report.reflections} of ${report.reflectionsAvailable} reflections have been completed.`;
  }
  // The tried-but-not-passed sentence is left out of the parts, because the screen draws it with
  // each module name as a button that opens that module's story.
  parts.rest = text.slice(`${name} has mastered ${list}.`.length).replace(/ Tried but not passed yet: [^]*?\.(?= [A-Z]|$)/, '').trim();
  summaryParagraph.lastParts = parts;
  return text;
}

// "Practice so far: 3 rounds, 1 passed." and the modules tried but not passed, each with its best
// score and number of tries. The report summary and the class view both read this, so they agree.
// Module titles are written in sentence case; educator lists show them in title case, small words aside.
// Story titles too (2026-09-24, Mikey), in the Chicago and AP habit: every word capitalized except the short articles,
// conjunctions and prepositions in the middle; the first and last words always capitalized; a word already in capitals kept.
const SMALL_WORDS = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'at', 'by', 'in', 'of', 'on', 'to', 'up', 'as', 'off', 'per', 'via', 'vs', 'into', 'onto', 'from', 'with']);
// titleCase (updated 2026-10-03, pass JE, Mikey: module titles shown as titles). In plain terms: capitalizes every word of a
// title except small joining words in the middle. Each part of a hyphenated word is capitalized (Two-Digit Numbers), and a lone
// letter or letter pair being taught keeps the case it was written in (The Silent e; Trace i, t and k; Sh, ch and th).
const LETTER_TOKEN = /^(?:[b-z]|ch|sh|th|wh|ph|ck|ng)[,.?!:;]?$/;
export function titleCase(text) {
  const words = String(text || '').split(' ');
  const cap = (part, inner) => { const core = part.toLowerCase().replace(/[^a-z]/g, ''); if (inner && SMALL_WORDS.has(core) && part === part.toLowerCase()) return part; return part.charAt(0).toUpperCase() + part.slice(1); };
  return words.map((w, i) => {
    if (i > 0 && LETTER_TOKEN.test(w)) return w;
    const inner = i > 0 && i < words.length - 1;
    return w.split('-').map((p, k) => cap(p, k > 0 || inner)).join('-');
  }).join(' ');
}
// The module a loop back returns to: the module before it in its course, else its first named prerequisite.
export function fundamentalsOf(moduleId) {
  const m = getModule(moduleId); if (!m) return null;
  const course = getCourse(m.courseId);
  const before = course ? course.modules.filter((x) => x.order < m.order).sort((a, b) => b.order - a.order)[0] : null;
  const target = before || (m.requires && m.requires.length ? getModule(m.requires[0]) : null);
  return target ? { id: target.id, title: target.title } : null;
}
const outOf = (score) => String(score).replace(' of ', ' out of ');
export function practiceLine(report) {
  const assigned = report.modules.filter((m) => report.enabledCourseIds.includes(m.courseId));
  if (report.totalAttempts === 0 && !assigned.some((m) => m.quickCheck)) return { line: '', tried: [] };
  const passedRounds = assigned.reduce((a, m) => a + (m.passes || 0), 0);
  const line = report.totalAttempts ? `Practice so far: ${report.totalAttempts} ${report.totalAttempts === 1 ? 'round' : 'rounds'}, ${passedRounds} passed.` : 'No practice rounds yet.';
  const subjectOf = (m) => { const c = getCourse(m.courseId); return c ? c.subject : ''; };
  const tried = assigned.filter((m) => m.attempts > 0 && !m.passed && !m.mastered).map((m) => ({ id: m.id, title: titleCase(m.title), subject: subjectOf(m), detail: `best attempt ${outOf(m.bestScore)}, ${m.attempts} ${m.attempts === 1 ? 'try' : 'tries'}`, short: `best score ${outOf(m.bestScore)}, ${m.attempts} ${m.attempts === 1 ? 'attempt' : 'attempts'}` }));
  // Quick checks too: a missed one is a try to skip that did not work, and a passed one is a module skipped.
  for (const m of assigned.filter((m) => m.quickCheck && !m.quickCheck.passed && !m.passed && !m.mastered && !tried.some((t) => t.id === m.id))) { const d = `quick check ${m.quickCheck.right} out of ${m.quickCheck.total}${m.quickCheck.guessed ? ', too fast to count' : ''}`; tried.push({ id: m.id, title: titleCase(m.title), subject: subjectOf(m), detail: d, short: d }); }
  const skipped = assigned.filter((m) => m.quickCheck && m.quickCheck.passed).map((m) => titleCase(m.title));
  return { line: skipped.length ? `${line} Skipped by quick check: ${skipped.join(', ')}.` : line, tried };
}

// The summary as a bulleted list plus the sentences that follow it.
export function summaryParts(report) {
  const text = summaryParagraph(report);
  const parts = summaryParagraph.lastParts;
  if (!parts || !parts.items.length) return { lead: text, items: [], rest: '' };
  return parts;
}

export function buildReport(learnerName, events) {
  const refresh = refresherIds(events);
  const progress = deriveProgress(events);
  const active = activeEvents(events);
  const modules = [...MODULES].sort((a, b) => a.courseId.localeCompare(b.courseId) || a.order - b.order).map((m) => {
    const p = progress.perModule[m.id];
    return {
      id: m.id,
      courseId: m.courseId,
      subject: getCourse(m.courseId).subject,
      courseTitle: getCourse(m.courseId).title,
      title: m.title,
      attempts: p.attempts,
      lessonViews: p.lessonViews,
      mastered: p.mastered,
      masteredAt: p.masteredAt,
      passed: p.passed,
      passes: p.passes,
      passDays: p.passDays.length,
      firstPassedAt: p.firstPassedAt,
      refresher: refresh.includes(m.id),
      placed: p.placed,
      pendingWriting: !!p.pendingWriting,
      bestScore: p.attempts ? `${p.bestCore} of ${moduleRules(m.id).questions}` : null,
      accuracyPercent: p.coreTotal ? Math.round((100 * p.coreCorrect) / p.coreTotal) : null,
      firstAttemptAt: p.firstAttemptAt,
      lastAttemptAt: p.lastAttemptAt,
      confidence: computeConfidence(m.id, events),
      quickCheck: active.filter((e) => e.type === 'quick_check' && e.moduleId === m.id).map((e) => ({ at: e.at, right: e.right, total: e.total, passed: e.passed, guessed: e.guessed })).pop() || null,
    };
  });
  return {
    notes: teacherNotes(events),
    coloringBreaks: coloringBreaks(events),
    learnerName,
    generatedAt: new Date().toISOString(),
    modulesMastered: progress.masteredIds.length,
    modulesTotal: MODULES.length,
    enabledCourseIds: enabledCourseIds(events), // a setting, not progress: it survives a reset
    totalAttempts: active.filter((e) => e.type === 'attempt_completed').length,
    reflections: active.filter((e) => e.type === 'wonder_answered').length,
    reflectionsAvailable: FEATURES.reflection ? WONDER.length : 0, // approval is applied on screen, where the review state lives
    retention: {
      asked: progress.review.asked,
      correct: progress.review.correct,
      percent: progress.review.asked ? Math.round((100 * progress.review.correct) / progress.review.asked) : null,
    },
    modules,
    definitions: [
      `Mastered: at least ${CONFIG.MASTERY_MIN_CORRECT} of the ${CONFIG.CORE_QUESTIONS_PER_ATTEMPT} core questions correct in a single practice set.`,
      'Accuracy: correct core answers divided by all core questions answered, across every attempt.',
      'Retention: review questions come from earlier mastered modules. They never affect mastery; they measure whether learning stuck.',
      'Attempts: completed practice sets. Only events after the most recent reset are counted.',
      'Every number is recomputed from the stored event log each time this report is opened.',
      'Reflections: Wonder questions answered. They are never graded, and the words a child writes are never stored.',
      ...CONFIDENCE_RULES,
    ],
  };
}

// ---------------------------------------------------------------------
// 6. BRAND — the logo (pure numbers; the screen draws it)
//
//    The sphere: short arcs that are real circles on a real sphere, seen
//    from the front, so they curve consistently and read as solid. Denser
//    and darker toward the lower right (light comes from the upper left).
//    Arcs that would cross the wordmark are skipped, so the letters stay
//    clear without a box behind them.
//
//    The wordmark: letters stored as outlines, not as a font name, so the
//    logo looks identical on every phone, browser, and printer. Rounded
//    corners come from stroking each letter with its own color.
// ---------------------------------------------------------------------

