// Lays a word out as SVG paths at a given size. Returns the paths and the width.
export function layoutWord(text, size, x, y, tracking = -0.02) {
  let cursor = x;
  const paths = [];
  for (const ch of text) {
    const g = WORDMARK_GLYPHS[ch];
    if (!g) continue;
    const adv = ((g.adv + tracking * 1000) * size) / 1000;
    // Each letter remembers its own middle, so the pointer can fade letters as well as arcs.
    paths.push({ d: g.d, transform: `translate(${cursor.toFixed(1)} ${y}) scale(${(size / 1000).toFixed(4)})`, cx: cursor + adv / 2, cy: y - size * 0.36 });
    cursor += adv;
  }
  return { paths, width: cursor - x, x, y, size };
}

// The sphere's arcs. keepOut: boxes (the two words) that no arc may cross.
export function buildSphereArcs(cx, cy, r, seed, keepOut, tries) {
  const rng = makeRng(seed);
  const segments = [];
  const hits = (x, y) => keepOut.some((b) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h);
  const norm = (v) => { const len = Math.hypot(v[0], v[1], v[2]); return [v[0] / len, v[1] / len, v[2] / len]; };
  for (let i = 0; i < tries; i++) {
    // A random circle around the sphere: pick an axis, then two directions square to it.
    const n = norm([rng() * 2 - 1, rng() * 2 - 1, rng() * 2 - 1]);
    const a = Math.abs(n[0]) < 0.9 ? [1, 0, 0] : [0, 1, 0];
    const u = norm([n[1] * a[2] - n[2] * a[1], n[2] * a[0] - n[0] * a[2], n[0] * a[1] - n[1] * a[0]]);
    const v = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
    const start = rng() * 6.283;
    const span = 1.1 + rng() * 1.3;
    const steps = Math.max(3, Math.round(span * 6));
    const pts = [];
    let depth = 0;
    let visible = true;
    for (let k = 0; k <= steps; k++) {
      const t = start + (span * k) / steps;
      const c = Math.cos(t); const sn = Math.sin(t);
      const p = [u[0] * c + v[0] * sn, u[1] * c + v[1] * sn, u[2] * c + v[2] * sn];
      if (p[2] < 0.05) { visible = false; break; } // behind the sphere, or right on the rim
      pts.push([cx + p[0] * r, cy - p[1] * r]);
      depth += p[2];
    }
    if (!visible) continue;
    const [mx, my] = pts[Math.floor(pts.length / 2)];
    if (pts.some(([x, y]) => hits(x, y))) continue;
    const towardLight = Math.max(0, Math.min(1, 0.5 + ((cx - mx) + (cy - my)) / (2 * r)));
    const low = Math.max(0, (my - cy) / r);
    if (rng() > 0.75 * (1 - 0.08 * low)) continue; // thin the weave, a little more near the bottom
    const z = depth / (steps + 1);
    segments.push({
      points: pts.map((p) => p.map((c) => c.toFixed(1)).join(',')).join(' '),
      width: Math.round((0.7 + 1.3 * z) * 0.8 * 100) / 100,
      opacity: Math.round((0.22 + 0.6 * z) * (1 - 0.25 * low) * 100) / 100,
      gold: rng() < 0.12,
      lit: towardLight,
    });
  }
  return segments;
}

// A few short gold flecks in the empty space on the left.
export function buildSphereFlecks(cx, cy, r, seed, keepOut, count) {
  const rng = makeRng(seed);
  const hits = (x, y) => keepOut.some((b) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h);
  const out = [];
  let guard = 0;
  while (out.length < count && guard++ < count * 60) {
    const a = rng() * 6.283;
    const rad = r * (0.35 + 0.6 * Math.sqrt(rng()));
    const x = cx + rad * Math.cos(a); const y = cy + rad * Math.sin(a);
    if (x >= cx - 10 || hits(x, y)) continue;
    const dir = rng() * 6.283; const len = 8 + rng() * 16;
    const x2 = x + len * Math.cos(dir); const y2 = y + len * Math.sin(dir);
    if (Math.hypot(x2 - cx, y2 - cy) > r * 0.98 || hits(x2, y2)) continue;
    out.push({ points: `${x.toFixed(1)},${y.toFixed(1)} ${x2.toFixed(1)},${y2.toFixed(1)}`, opacity: Math.round((0.35 + 0.35 * rng()) * 100) / 100 });
  }
  return out;
}

// The single gold arc under the wordmark, bowing the opposite way to the arcs above.
export function buildAccentArc(x0, x1, y, lift) {
  const pts = [];
  for (let i = 0; i <= 12; i++) {
    const t = i / 12;
    pts.push(`${(x0 + (x1 - x0) * t).toFixed(1)},${(y + lift * Math.sin(Math.PI * t)).toFixed(1)}`);
  }
  return pts.join(' ');
}

// ---------- The printed book with paintings (2026-09-24, Mikey) ----------
// A painted story may need more than one sheet. The book splits it between paragraphs, never between a paragraph and its
// picture, so a sentence about the ball and the painting of the ball always share a page. Sizes are in inches on a letter
// page: the room left inside the padding and above the footer, a line of 17px story text, how many words fit a line at full
// width and beside a picture, the title block, the main painting (about half wide) and a side painting (two fifths wide),
// measured from a real print so a grade 3 story with six paintings fills two sheets rather than three.
export const PRINT_PAGE = { room: 8.95, line: 0.27, perLine: 12, perSideLine: 6, head: 1.0, main: 2.65, side: 2.05, gap: 0.12, more: 0.6 };
export function printParts(words, paintedAfter = [], mainPainted = false) {
  const P = PRINT_PAGE; const count = (t) => String(t).split(/\s+/).filter(Boolean).length;
  const cost = (i) => (paintedAfter.includes(i) ? Math.max(Math.ceil(count(words[i]) / P.perSideLine) * P.line, P.side) : Math.ceil(count(words[i]) / P.perLine) * P.line) + P.gap;
  const parts = []; let part = { head: true, from: 0, to: -1, used: P.head + (mainPainted ? P.main : 0) };
  words.forEach((_, i) => {
    if (part.to >= part.from && part.used + cost(i) > P.room) { parts.push(part); part = { head: false, from: i, to: i - 1, used: P.more }; }
    part.to = i; part.used += cost(i);
  });
  parts.push(part);
  // `used` is the inches of the sheet the part fills (2026-09-28, pass FR): the rule test reads it to prove every page fits,
  // so no paragraph is ever tall enough to be cut off or parted from its picture.
  return parts.map(({ head, from, to, used }) => ({ head, from, to, used: Math.round(used * 100) / 100 }));
}

// ---------- The story book's pages and the Story Log's lists (2026-09-28, Mikey, pass FR) ----------
// The printed book decides its pages here, not on the screen, so a rule test can turn every course into pages exactly the
// way the book does, twice: once with no painting yet and once as if every painting had arrived. `chapters` are the
// course's modules that have a story, in course order, as { m, st }; `hasArt(serial)` says whether a painting exists.
// Short stories go two to a page while neither is painted and under 260 words (the dense face); a painted story, or one
// that needs more than one sheet, takes a page per part from printParts, which splits only between paragraphs. The long
// story comes last, on as many sheets as it needs. Nothing here knows about screens or printers, only sizes.
export function bookPages(chapters, courseStory, hasArt) {
  const painted = (st) => [st.art, ...(st.more || []).map((m) => m.serial)].some(hasArt);
  const partsOf = (st) => printParts(st.words, (st.more || []).filter((m) => hasArt(m.serial)).map((m) => m.after), hasArt(st.art));
  const words = (st) => st.words.join(' ').split(/\s+/).length;
  const fit = (st) => (painted(st) ? 1 : words(st) <= 260 ? 2 : 1);
  const groups = [];
  chapters.forEach((ch, i) => {
    const parts = partsOf(ch.st);
    if (painted(ch.st) || parts.length > 1) { parts.forEach((part) => groups.push({ per: 1, items: [{ ...ch, i, part }] })); return; }
    const per = fit(ch.st); const last = groups[groups.length - 1];
    if (per > 1 && last && last.per === per && last.items.length < per) last.items.push({ ...ch, i }); else groups.push({ per, items: [{ ...ch, i }] });
  });
  const csParts = courseStory ? partsOf(courseStory) : [];
  return { groups, csParts };
}
// Everything a student's Story Log can list: every module story on a course the student has, and every long story of
// those courses, each with when it was first read (null when unread). A long story unlocks when every module of its
// course is mastered; `left` counts the modules still to master. The screen sorts these into Most recent, Read and Unread
// and never decides on its own what exists, so a story that is missing here is missing everywhere, and the rule test
// checks that none is.
export function storyLogAvailable(events, storyFor, courseStoryFor) {
  const readAt = new Map(storiesRead(events).map((r) => [r.moduleId, r.at]));
  const mastered = new Set(deriveProgress(events).masteredIds);
  const courses = enabledCourseIds(events).map((cid) => getCourse(cid)).filter(Boolean);
  const shorts = courses.flatMap((c) => c.modules.filter((m) => storyFor(m.id)).map((m) => ({ moduleId: m.id, courseId: c.id, at: readAt.get(m.id) || null })));
  const longs = courses.filter((c) => courseStoryFor(c.id)).map((c) => ({ moduleId: `course:${c.id}`, courseId: c.id, unlocked: c.modules.every((m) => mastered.has(m.id)), left: c.modules.filter((m) => !mastered.has(m.id)).length, at: readAt.get(`course:${c.id}`) || null }));
  return { shorts, longs };
}
// Most recent reading, newest first: everything read today (the device's day) or, when nothing was read today, the last
// three stories opened. Before pass FR the screen took the first three ever read, since storiesRead lists first openings
// in the order they happened, so an old reader's Most recent showed the stories they began with.
export function recentReads(events, now = new Date()) {
  const read = storiesRead(events).slice().reverse();
  const dayOf = (at) => { const d = new Date(at); return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`; };
  const today = dayOf(now); const todays = read.filter((r) => dayOf(r.at) === today);
  return todays.length ? todays : read.slice(0, 3);
}

// ---------- Coloring pages from lessons (2026-09-24, Mikey) ----------
// Given the lessons a student has passed, a way to ask whether a page's art exists, and the pages themselves
// (COLOR_PAGES), this returns the picture ids to show in Let's Color, in the order the lessons were passed.
export function lessonColorPages(passedIds, hasArt, pages) {
  return passedIds.filter((id) => pages[id] && hasArt(pages[id][0])).map((id) => `lesson-${id}`);
}

